# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# ----------------------------
# ENUMERATIONS
# ----------------------------

class UserRole(Enum):
    COACH = "coach"
    ANALYST = "analyst"
    PLAYER = "player"

class DataType(Enum):
    VIDEO = "video"
    CSV = "csv"
    LIVE_STREAM = "live_stream"

class MetricType(Enum):
    SPEED = "speed"
    DISTANCE = "distance"
    HEART_RATE = "heart_rate"
    ACCURACY = "accuracy"
    EFFICIENCY = "efficiency"
    PASS_COMPLETION = "pass_completion"
    TACKLES = "tackles"
    GOALS = "goals"

# ----------------------------
# DATA CLASSES
# ----------------------------

@dataclass
class User:
    id: str
    username: str
    email: str
    role: UserRole
    team_id: str
    created_at: datetime = field(default_factory=datetime.now)

@dataclass
class MatchData:
    id: str
    name: str
    type: DataType
    file_path: Optional[str] = None
    stream_url: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    uploaded_by: str = ""
    uploaded_at: datetime = field(default_factory=datetime.now)
    processed: bool = False
    team_id: str = ""

@dataclass
class PlayerPerformance:
    player_id: str
    match_id: str
    metrics: Dict[MetricType, float] = field(default_factory=dict)
    timestamp: datetime = field(default_factory=datetime.now)

@dataclass
class Report:
    id: str
    title: str
    author_id: str
    match_id: str
    content: Dict[str, Any]
    created_at: datetime = field(default_factory=datetime.now)
    last_updated: datetime = field(default_factory=datetime.now)
    shared_with: List[str] = field(default_factory=list)

@dataclass
class CollaborationItem:
    id: str
    match_id: str
    user_id: str
    content: str
    type: str  # "note", "comment", "chat"
    timestamp: datetime = field(default_factory=datetime.now)
    parent_id: Optional[str] = None  # for threaded comments

@dataclass
class Team:
    id: str
    name: str
    members: List[str] = field(default_factory=list)
    created_at: datetime = field(default_factory=datetime.now)

# ----------------------------
# STORAGE SIMULATION (IN-MEMORY FOR DEMO)
# ----------------------------

class DataStore:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.teams: Dict[str, Team] = {}
        self.match_data: Dict[str, MatchData] = {}
        self.player_performance: Dict[str, List[PlayerPerformance]] = defaultdict(list)
        self.reports: Dict[str, Report] = {}
        self.collaboration_items: List[CollaborationItem] = []
        self.lock = threading.RLock()  # Reentrant lock for thread safety
        self.file_storage: Dict[str, bytes] = {}  # Simulate file storage
        self.live_streams: Dict[str, Queue] = {}  # Live data stream queues

    def add_user(self, user: User):
        with self.lock:
            self.users[user.id] = user
            # Auto-create team if not exists
            if user.team_id not in self.teams:
                self.teams[user.team_id] = Team(id=user.team_id, name=f"Team {user.team_id}")
            self.teams[user.team_id].members.append(user.id)

    def get_user(self, user_id: str) -> Optional[User]:
        with self.lock:
            return self.users.get(user_id)

    def add_match_data(self, match: MatchData):
        with self.lock:
            self.match_data[match.id] = match

    def get_match_data(self, match_id: str) -> Optional[MatchData]:
        with self.lock:
            return self.match_data.get(match_id)

    def add_player_performance(self, perf: PlayerPerformance):
        with self.lock:
            self.player_performance[perf.player_id].append(perf)

    def get_player_performance(self, player_id: str, match_id: str) -> List[PlayerPerformance]:
        with self.lock:
            return [p for p in self.player_performance[player_id] if p.match_id == match_id]

    def add_report(self, report: Report):
        with self.lock:
            self.reports[report.id] = report

    def get_reports_for_match(self, match_id: str) -> List[Report]:
        with self.lock:
            return [r for r in self.reports.values() if r.match_id == match_id]

    def add_collaboration_item(self, item: CollaborationItem):
        with self.lock:
            self.collaboration_items.append(item)

    def get_collaboration_items(self, match_id: str) -> List[CollaborationItem]:
        with self.lock:
            return [item for item in self.collaboration_items if item.match_id == match_id]

    def save_file(self, file_id: str, content: bytes):
        with self.lock:
            self.file_storage[file_id] = content

    def get_file(self, file_id: str) -> Optional[bytes]:
        with self.lock:
            return self.file_storage.get(file_id)

    def create_live_stream(self, stream_id: str):
        with self.lock:
            self.live_streams[stream_id] = Queue()

    def push_to_live_stream(self, stream_id: str, data: Any):
        with self.lock:
            if stream_id in self.live_streams:
                self.live_streams[stream_id].put_nowait(data)

    def get_live_stream(self, stream_id: str) -> Optional[Queue]:
        with self.lock:
            return self.live_streams.get(stream_id)

# Global instance
store = DataStore()

# ----------------------------
# AUTHORIZATION & PERMISSIONS
# ----------------------------

class AccessControl:
    @staticmethod
    def can_view_match(user: User, match_id: str) -> bool:
        match = store.get_match_data(match_id)
        if not match:
            return False
        user_team = store.teams.get(user.team_id)
        if not user_team:
            return False
        return match.team_id == user.team_id

    @staticmethod
    def can_edit_match(user: User, match_id: str) -> bool:
        if user.role == UserRole.COACH:
            return AccessControl.can_view_match(user, match_id)
        elif user.role == UserRole.ANALYST:
            return AccessControl.can_view_match(user, match_id)
        else:  # PLAYER
            return False

    @staticmethod
    def can_generate_report(user: User) -> bool:
        return user.role in [UserRole.COACH, UserRole.ANALYST]

    @staticmethod
    def can_share_report(user: User, report_id: str) -> bool:
        report = store.reports.get(report_id)
        if not report:
            return False
        return report.author_id == user.id and user.role in [UserRole.COACH, UserRole.ANALYST]

    @staticmethod
    def can_add_comment(user: User, match_id: str) -> bool:
        return AccessControl.can_view_match(user, match_id)

# ----------------------------
# FILE PROCESSING
# ----------------------------

class FileProcessor:
    @staticmethod
    def process_csv(file_path: str, match_id: str, team_id: str) -> List[PlayerPerformance]:
        performances = []
        try:
            with open(file_path, 'r') as f:
                reader = csv.DictReader(f)
                for row in reader:
                    player_id = row.get('player_id', '')
                    if not player_id:
                        continue
                    perf = PlayerPerformance(
                        player_id=player_id,
                        match_id=match_id,
                        metrics={}
                    )
                    for metric_name, value in row.items():
                        if metric_name in ['player_id', 'timestamp']:
                            continue
                        try:
                            metric_type = MetricType(metric_name)
                            perf.metrics[metric_type] = float

