@dataclass
class Position:
    x: int
    y: int
    z: int  # 3D space for interstellar map

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)

    def __hash__(self):
        return hash((self.x, self.y, self.z))

    def __eq__(self, other):
        return isinstance(other, Position) and (self.x, self.y, self.z) == (other.x, other.y, other.z)

@dataclass
class Resource:
    type: ResourceType
    amount: float = 0.0

    def add(self, amount: float):
        self.amount += amount

    def remove(self, amount: float) -> bool:
        if self.amount >= amount:
            self.amount -= amount
            return True
        return False

@dataclass
class Building:
    id: str
    type: BuildingType
    position: Position
    health: float = 100.0
    production_queue: List[str] = field(default_factory=list)  # e.g., "FRIGATE", "ADVANCED_PROPULSION"
