    owner: Optional[str] = None
    target: Optional[Position] = None
    mission: Optional[str] = None  # e.g., "patrol", "attack", "escort"

    def is_destroyed(self) -> bool:
        return self.health <= 0

@dataclass
class TechnologyTree:
    researched: Set[Technology] = field(default_factory=set)
    queue: List[Technology] = field(default_factory=list)
    progress: Dict[Technology, float] = field(default_factory=dict)

    def is_researched(self, tech: Technology) -> bool:
        return tech in self.researched

    def begin_research(self, tech: Technology):
        if not self.is_researched(tech):
            self.queue.append(tech)
            self.progress[tech] = 0.0

    def update_progress(self, tech: Technology, amount: float):
        if tech in self.progress:
            self.progress[tech] += amount
            if self.progress[tech] >= 1.0:
                self.researched.add(tech)
                del self.progress[tech]
                self.queue.remove(tech)

@dataclass
class Empire:
    id: str
    name: str
    colony_center: Optional[Building] = None
