    def __post_init__(self):
        for r in ResourceType:
            self.resources[r] = Resource(r, 0.0)

    def add_resource(self, resource_type: ResourceType, amount: float):
        self.resources[resource_type].add(amount)

    def spend_resources(self, cost: Dict[ResourceType, float]) -> bool:
        for r_type, amount in cost.items():
            if not self.resources[r_type].remove(amount):
                return False
        return True

    def calculate_score(self) -> float:
        territory_score = len(self.territory) * 10
        tech_score = len(self.tech_tree.researched) * 20
