}

# Event weights and types
EVENT_TYPES = [
    "Alien_Invasion", "Asteroid_Belt", "Resource_Depletion", "Diplomatic_Crisis", "Technological_Breakthrough", "Pirate_Ambush"
]
EVENT_WEIGHTS = [0.2, 0.15, 0.15, 0.15, 0.1, 0.25]  # Probabilities summing to 1.0

# -----------------------------
# Data Structures
# -----------------------------

class ResourceType(Enum):
    ENERGY = "energy"
