    def __hash__(self):
        return hash((self.x, self.y))

    def __eq__(self, other):
        return isinstance(other, Position) and self.x == other.x and self.y == other.y

@dataclass
class ResourcePool:
    energy: float = 0
    minerals: float = 0
    food: float = 0

    def can_afford(self, costs: Dict[str, float]) -> bool:
        return all(self.get(resource) >= amount for resource, amount in costs.items())

    def spend(self, costs: Dict[str, float]) -> None:
        for resource, amount in costs.items():
            setattr(self, resource, max(0, getattr(self, resource) - amount))

    def earn(self, gains: Dict[str, float]) -> None:
        for resource, amount in gains.items():
            setattr(self, resource, getattr(self, resource) + amount)

    def get(self, resource: str) -> float:
        return getattr(self, resource, 0)

    def to_dict(self) -> Dict[str, float]:
        return {"energy": self.energy, "minerals": self.minerals, "food": self.food}

@dataclass
class Building:
    type: BuildingType
    position: Position
    owner_id: int
    level: int = 1
    is_under_construction: bool = False
    construction_progress: float = 0.0

    def get_production_rate(self) -> Dict[str, float]:
        rates = {
            BuildingType.COLONY_BASE: {"energy": 5, "minerals": 0, "food": 3},
            BuildingType.MINE: {"energy": 0, "minerals": 10, "food": 0},
            BuildingType.FARM: {"energy": 0, "minerals": 0, "food": 8},
            BuildingType.RESEARCH_LAB: {"energy": 0, "minerals": 0, "food": 0}
        }
        base = rates.get(self.type, {"energy": 0, "minerals": 0, "food": 0})
        return {r: v * self.level for r, v in base.items()}

@dataclass
class Unit:
    type: UnitType
    position: Position
    owner_id: int
    health: float = 100.0
    speed: float = 1.0
    attack: float = 20.0
    defense: float = 10.0
    target: Optional[Position] = None
    is_moving: bool = False

    def move_toward(self, target: Position) -> None:
        self.target = target
        self.is_moving = True

    def update_position(self, step: float = 0.1) -> bool:
        if not self.target:
            self.is_moving = False
            return False
        dx = self.target.x - self.position.x
        dy = self.target.y - self.position.y
        dist = math.sqrt(dx*dx + dy*dy)
        if dist < step:
            self.position = self.target
            self.target = None
            self.is_moving = False
            return True
        else:
            self.position.x += (dx / dist) * step * self.speed
            self.position.y += (dy / dist) * step * self.speed
            return False

@dataclass
class TechnologyTree:
    researched: Set[str] = field(default_factory=set)
    pending: Set[str] = field(default_factory=set)
    progress: Dict[str, float] = field(default_factory=lambda: defaultdict(float))

    def can_research(self, tech: str) -> bool:
