class Priority(Enum):
    LOW = "Low"
    MEDIUM = "Medium"
    HIGH = "High"
    URGENT = "Urgent"

class ResourceType(Enum):
    PERSONNEL = "Personnel"
    EQUIPMENT = "Equipment"
    BUDGET = "Budget"

@dataclass
class Task:
    id: str
    description: str
    due_date: datetime
    priority: Priority
    assigned_team_members: List[str] = field(default_factory=list)
    dependencies: List[str] = field(default_factory=list)  # task_ids
    status: str = "Pending"  # Pending, In Progress, Completed
    start_date: Optional[datetime] = None
    end_date: Optional[datetime] = None

    def __post_init__(self):
        if not self.id:
            raise ValueError("Task must have an ID")

@dataclass
class Resource:
    name: str
    type: ResourceType
    capacity: float  # e.g., hours for personnel, dollars for budget, units for equipment
    allocated: float = 0.0

    @property
    def available(self) -> float:
        return self.capacity - self.allocated

    def is_over_allocated(self) -> bool:
        return self.allocated > self.capacity

    def allocate(self, amount: float) -> bool:
        if amount < 0:
            raise ValueError("Allocation amount cannot be negative")
        if self.allocated + amount > self.capacity:
            return False  # Over-allocation would occur
        self.allocated += amount
        return True

    def deallocate(self, amount: float):
        if amount < 0:
            raise ValueError("Deallocation amount cannot be negative")
        self.allocated = max(0, self.allocated - amount)

@dataclass
class TaskResourceAllocation:
    task_id: str
    resource_name: str
    amount: float

# =============================
# CORE MODULES
