class TaskManager:
    def __init__(self):
        self.tasks: Dict[str, Task] = {}
        self.next_id = 1

    def create_task(self, description: str, due_date: datetime, priority: Priority, assigned_team_members: List[str]) -> str:
        task_id = f"T{self.next_id}"
        self.next_id += 1
        task = Task(
            id=task_id,
            description=description,
            due_date=due_date,
            priority=priority,
            assigned_team_members=assigned_team_members
        )
        self.tasks[task_id] = task
        logger.info(f"Task created: {task_id} - {description}")
        return task_id

    def edit_task(self, task_id: str, **kwargs) -> bool:
        if task_id not in self.tasks:
            return False
        task = self.tasks[task_id]
        for key, value in kwargs.items():
            if hasattr(task, key):
                if key == 'due_date' and not isinstance(value, datetime):
                    raise ValueError("due_date must be a datetime object")
                if key == 'priority' and not isinstance(value, Priority):
                    raise ValueError("priority must be a Priority enum")
                if key == 'assigned_team_members' and not isinstance(value, list):
                    raise ValueError("assigned_team_members must be a list")
                setattr(task, key, value)
        logger.info(f"Task updated: {task_id}")
        return True

    def delete_task(self, task_id: str) -> bool:
        if task_id not in self.tasks:
            return False
        del self.tasks[task_id]
        logger.info(f"Task deleted: {task_id}")
        return True

    def get_task(self, task_id: str) -> Optional[Task]:
        return self.tasks.get(task_id)

    def get_all_tasks(self) -> List[Task]:
        return list(self.tasks.values())

    def get_tasks_by_status(self, status: str) -> List[Task]:
        return [task for task in self.tasks.values() if task.status == status]

    def get_tasks_by_priority(self, priority: Priority) -> List[Task]:
        return [task for task in self.tasks.values() if task.priority == priority]

    def get_tasks_by_assignee(self, team_member: str) -> List[Task]:
        return [task for task in self.tasks.values() if team_member in task.assigned_team_members]

class Scheduler:
    def __init__(self, task_manager: TaskManager):
        self.task_manager = task_manager
        self.task_dependencies: Dict[str, Set[str]] = defaultdict(set)  # task_id -> set of dependent task_ids
        self.dependents: Dict[str, Set[str]] = defaultdict(set)  # task_id -> set of tasks depending on it
        self.scheduled_tasks: List[Tuple[datetime, str]] = []  # (start_time, task_id)
        self.lock = threading.Lock()

    def add_dependency(self, task_id: str, dependent_task_id: str) -> bool:
        if task_id not in self.task_manager.tasks or dependent_task_id not in self.task_manager.tasks:
            return False
        if task_id == dependent_task_id:
            return False
        if dependent_task_id in self.task_dependencies[task_id]:
            return False
        self.task_dependencies[dependent_task_id].add(task_id)
        self.dependents[task_id].add(dependent_task_id)
        logger.info(f"Dependency added: {dependent_task_id} depends on {task_id}")
        return True

    def remove_dependency(self, task_id: str, dependent_task_id: str) -> bool:
        if dependent_task_id not in self.task_dependencies or task_id not in self.task_dependencies[dependent_task_id]:
            return False
        self.task_dependencies[dependent_task_id].remove(task_id)
        self.dependents[task_id].remove(dependent_task_id)
        logger.info(f"Dependency removed: {dependent_task_id} no longer depends on {task_id}")
        return True

    def schedule_tasks(self) -> List[Dict[str, Any]]:
        """Schedule tasks based on dependencies and priority. Returns scheduled tasks with start/end times."""
        with self.lock:
            self.scheduled_tasks.clear()
            ready_tasks = []
            remaining_tasks = set(self.task_manager.tasks.keys())

            # Initialize: find tasks with no dependencies
            for task_id in remaining_tasks:
