import datetime
import json
from typing import List, Dict, Optional, Set
from enum import Enum


class PriorityLevel(Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"


class Task:
    def __init__(self, task_id: str, description: str, due_date: datetime.date, priority: PriorityLevel, assigned_to: List[str]):
        self.task_id = task_id
        self.description = description
        self.due_date = due_date
        self.priority = priority
        self.assigned_to = assigned_to  # List of team member names
        self.status = "pending"  # pending, in_progress, completed
        self.dependencies: List[str] = []  # List of task_ids that must be completed before this one
        self.start_date: Optional[datetime.date] = None

    def to_dict(self):
        return {
            "task_id": self.task_id,
            "description": self.description,
            "due_date": self.due_date.isoformat(),
            "priority": self.priority.value,
            "assigned_to": self.assigned_to,
            "status": self.status,
            "dependencies": self.dependencies,
            "start_date": self.start_date.isoformat() if self.start_date else None
        }

    @classmethod
    def from_dict(cls, data):
        task = cls(
            task_id=data["task_id"],
            description=data["description"],
            due_date=datetime.date.fromisoformat(data["due_date"]),
            priority=PriorityLevel(data["priority"]),
            assigned_to=data["assigned_to"]
        )
        task.status = data["status"]
        task.dependencies = data["dependencies"]
        if data["start_date"]:
            task.start_date = datetime.date.fromisoformat(data["start_date"])
        return task


class Resource:
    def __init__(self, name: str, resource_type: str, capacity: int):
        self.name = name
        self.resource_type = resource_type  # 'personnel', 'equipment', 'budget'
        self.capacity = capacity  # max units available (e.g., hours, dollars, units)
        self.allocated = 0  # currently allocated units

    def allocate(self, units: int) -> bool:
        if self.allocated + units <= self.capacity:
            self.allocated += units
            return True
        return False

    def release(self, units: int):
        self.allocated = max(0, self.allocated - units)

    def utilization(self) -> float:
        return self.allocated / self.capacity if self.capacity > 0 else 0.0

    def is_overallocated(self) -> bool:
        return self.allocated > self.capacity

    def to_dict(self):
        return {
            "name": self.name,
            "resource_type": self.resource_type,
            "capacity": self.capacity,
            "allocated": self.allocated
        }

    @classmethod
    def from_dict(cls, data):
        resource = cls(data["name"], data["resource_type"], data["capacity"])
        resource.allocated = data["allocated"]
        return resource


