        if "dependencies" in kwargs:
            task.dependencies = kwargs["dependencies"]
            self._check_dependencies(task_id)

        # Re-evaluate scheduling and resource allocation if task changed
        self._schedule_tasks()
        self._allocate_resources()

        return True

    def delete_task(self, task_id: str) -> bool:
        if task_id not in self.tasks:
            return False

        task = self.tasks[task_id]

        # Release allocated resources
        for resource_name, allocated_units in self._get_task_resource_allocations(task_id).items():
            if resource_name in self.resources:
                self.resources[resource_name].release(allocated_units)

        # Remove from dependencies of other tasks
        for tid, t in self.tasks.items():
            if task_id in t.dependencies:
                t.dependencies.remove(task_id)

        del self.tasks[task_id]

        # Reschedule and reallocate
        self._schedule_tasks()
        self._allocate_resources()

        return True

    def _check_dependencies(self, task_id: str):
        task = self.tasks[task_id]
        for dep_id in task.dependencies:
            if dep_id not in self.tasks:
                raise ValueError(f"Dependency task {dep_id} does not exist.")
            if self.tasks[dep_id].status == "completed":
                continue  # Already done
            # If dependent task is not completed, mark current task as blocked
            if task.status != "blocked":
                task.status = "blocked"

    def complete_task(self, task_id: str) -> bool:
        if task_id not in self.tasks:
            return False

        task = self.tasks[task_id]
        if task.status == "completed":
            return False

        task.status = "completed"
        self._notify_task_completed(task)

        # Update dependent tasks
        for tid, t in self.tasks.items():
            if task_id in t.dependencies:
                # Check if all dependencies are now complete
                if all(self.tasks[dep].status == "completed" for dep in t.dependencies):
                    t.status = "pending"  # Now ready to be scheduled
                    self._notify_dependency_resolved(t)

        # Re-schedule and reallocate resources
        self._schedule_tasks()
        self._allocate_resources()

        return True

    def _schedule_tasks(self):
        # Sort tasks by priority (HIGH > MEDIUM > LOW) and then by due date
        sorted_tasks = sorted(
            self.tasks.values(), 
            key=lambda t: (
                -t.priority.value,  # HIGH=0, MEDIUM=1, LOW=2 (reverse for priority)
                t.due_date
            )
        )

        current_date = datetime.date.today()

        # Reset start dates
        for task in self.tasks.values():
            task.start_date = None

        # Schedule tasks based on dependencies and priority
        scheduled = set()
        while len(scheduled) < len(self.tasks):
            task_scheduled = False
            for task in sorted_tasks:
                if task.task_id in scheduled:
                    continue
                if task.status == "completed":
                    scheduled.add(task.task_id)
                    continue
                # Check if all dependencies are completed
                if all(self.tasks[dep].status == "completed" for dep in task.dependencies):
                    # If not blocked and not scheduled, assign earliest possible start date
                    if task.status != "blocked":
                        # Start on first available day after current_date and due_date not passed
                        task.start_date = max(current_date, task.due_date - datetime.timedelta(days=1))
                        scheduled.add(task.task_id)
                        task_scheduled = True
            if not task_scheduled:
                # Break if no task can be scheduled (cyclic dependency or unresolved blockers)
                break

    def add_resource(self, name: str, resource_type: str, capacity: int):
        if name in self.resources:
            raise ValueError(f"Resource {name} already exists.")
        self.resources[name]

