@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def length(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / length, self.y / length)

    def distance_to(self, other):
        return (self - other).length()

@dataclass
class Robot:
    id: str
    team: Team
    robot_type: RobotType
    position: Vector2D
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    speed: float = 1.0
    weapon: WeaponType = WeaponType.RIFLE
    weapon_cooldown: float = 0.0
    recharge_rate: float = 0.05
    energy: float = 100.0
    max_energy: float = 100.0
    is_alive: bool = True
    last_action: str = "idle"
    target: Optional[str] = None
    role: str = "default"
    knowledge_base: Dict = field(default_factory=dict)
    strategy_history: List = field(default_factory=list)

    def take_damage(self, damage: float) -> float:
        """Apply damage to robot, considering armor."""
        effective_damage = damage * (1 - min(self.armor / 100, 0.75))
        self.health -= effective_damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
        return effective_damage

    def heal(self, amount: float) -> float:
        """Heal robot, up to max health."""
        heal_amount = min(amount, self.max_health - self.health)
        self.health += heal_amount
        return heal_amount

    def recharge_energy(self, amount: float) -> float:
        """Recharge robot's energy, up to max energy."""
        recharge_amount = min(amount, self.max_energy - self.energy)
        self.energy += recharge_amount
        return recharge_amount

    def update_cooldown(self, dt: float):
        """Update weapon cooldown."""
        if self.weapon_cooldown > 0:
            self.weapon_cooldown -= dt

    def can_attack(self) -> bool:
        """Check if robot is ready to attack."""
        return self.weapon_cooldown <= 0 and self.is_alive and self.energy >= 10

    def use_weapon(self, target_position: Vector2D, game_state: 'GameState') -> Dict:
        """Use current weapon and return attack results."""
        if not self.can_attack():
            return {"success": False, "damage": 0, "energy_used": 0, "effect": None}

        # Calculate energy cost based on weapon
        energy_costs = {
            WeaponType.RIFLE: 10,
            WeaponType.SHOTGUN: 15,
            WeaponType.SNIPER: 25,
            WeaponType.LAUNCHER: 35,
            WeaponType.MELEE: 5,
            WeaponType.HEALING_GUN: 20
        }

        damage_values = {
            WeaponType.RIFLE: 15,
            WeaponType.SHOTGUN: 30,
            WeaponType.SNIPER: 50,
            WeaponType.LAUNCHER: 70,
            WeaponType.MELEE: 40,
            WeaponType.HEALING_GUN: 0
        }

        cooldowns = {
            WeaponType.RIFLE: 0.5,
            WeaponType.SHOTGUN: 1.0,
            WeaponType.SNIPER: 2.0,
            WeaponType.LAUNCHER: 3.0,
            WeaponType.MELEE: 0.8,
            WeaponType.HEALING_GUN: 1.5
        }

        energy_cost = energy_costs.get(self.weapon, 10)
        damage = damage_values.get(self.weapon, 15)
        cooldown = cooldowns.get(self.weapon, 0.5)

        if self.energy < energy_cost:
            return {"success": False, "damage": 0, "energy_used": 0, "effect": None}

        self.energy -= energy_cost
        self.weapon_cooldown = cooldown
        self.last_action = "attack"

        # Calculate distance to target
        distance = self.position.distance_to(target_position)

        # Adjust damage based on distance for ranged weapons
        if self.weapon in [WeaponType.RIFLE, WeaponType.SHOTGUN, WeaponType.SNIPER, WeaponType.LAUNCHER]:
            if distance > 50:
                damage *= 0.5  # Reduced damage at long range
            elif distance > 30:
                damage *= 0.75

        # For melee, only work if very close
        if self.weapon == WeaponType.MELEE and distance > 3:
            return {"success": False, "damage": 0, "energy_used": energy_cost, "effect": None}

        # Find target robot
        target_robot = None
        for robot in game_state.robots.values():
            if robot.is_alive and robot.position.distance_to(target_position) < 2:
                target_robot = robot
                break

        if target_robot is None:
            return {"success": False, "damage": 0, "energy_used": energy_cost, "effect": None}

        # Apply damage
        actual_damage = target_robot.take_damage(damage)

        # Apply special effects
        effect = None
        if self.weapon == WeaponType.HEALING_GUN:
            target_robot.heal(damage)
            effect = "heal"
        elif self.weapon == WeaponType.LAUNCHER:
            effect = "explosion"

        return {
            "success": True,
            "damage": actual_damage,
            "energy_used": energy_cost,
            "effect": effect,
            "target_id": target_robot.id
        }

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def is_expired(self, current_time: float) -> bool:
        return current_time - self.spawn_time > self.duration

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float = 5.0
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def affect_robot(self, robot: Robot) -> float:
        """Apply hazard effect to robot and return damage."""
        if not self.active or not robot.is_alive:
            return 0

        distance = robot.position.distance_to(self.position)
        if distance <= self.radius:
            # Apply damage based on proximity (more damage when closer)
            damage_multiplier = 1.0 - (distance / self.radius)
            damage = self.damage_per_second * damage_multiplier
            robot.take_damage(damage)
            return damage
        return 0

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    progress: float = 0.0
    max_progress: float = 100.0
    team_required: Optional[Team] = None
    captured_by: Optional[Team] = None
    defenders: List[str] = field(default_factory=list)
    escort_targets: List[Vector2D] = field(default_factory=list)
    current_target_index: int = 0

    def update(self, game_state: 'GameState', dt: float):
        """Update objective progress based on game state."""
        if self.type == ObjectiveType.CAPTURE_FLAG:
            # Count robots from required team near flag
            nearby_robots = 0
            for robot in game_state.robots.values():
                if (robot.is_alive and robot.team == self.team_required and 
                    robot.position.distance_to(self.position) < 5):
                    nearby_robots += 1

            # Progress increases with more robots nearby
            if nearby_robots > 0:
                self.progress += nearby_robots * dt * 5
                if self.progress >= self.max_progress:
                    self.progress = self.max_progress
                    self.captured_by = self.team_required
            else:
                # Reduce progress if no team members nearby
                if self.captured_by and self.captured_by != self.team_required:
                    self.progress -= dt * 2
                    if self.progress <= 0:
                        self.captured_by = None

        elif self.type == ObjectiveType.ESCAPE_PAYLOAD:
            # Find robot escorting payload
            escorting_robot = None
            for robot in game_state.robots.values():
                if (robot.is_alive and robot.team == self.team_required and 
                    robot.position.distance_to(self.position) < 3):
                    escorting_robot = robot
                    break

            if escorting_robot:
                # Move payload toward next target
                if self.current_target_index < len(self.escort_targets):
                    target = self.escort_targets[self.current_target_index]
                    direction = (target - self.position).normalize()
                    self.position = self.position + direction * dt * 10

                    # Check if reached target
                    if self.position.distance_to(target) < 2:
                        self.current_target_index += 1
                        if self.current_target_index >= len(self.escort_targets):
                            self.progress = 100
                self.progress += dt * 2
            else:
                # Payload slows if not escorted
                self.progress += dt * 0.5

@dataclass
class GameState:
    """Contains all game state information."""
    robots: Dict[str, Robot] = field(default_factory=dict)
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
