    audio_events: List[Dict] = field(default_factory=list)  # For audio effects

    def add_robot(self, robot: Robot):
        self.robots[robot.id] = robot
        if robot.team not in self.spawn_points:
            self.spawn_points[robot.team] = []

    def get_team_robots(self, team: Team) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.team == team and robot.is_alive]

    def get_alive_robots(self) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.is_alive]

    def get_opposing_team(self, team: Team) -> Team:
        return Team.BLUE if team == Team.RED else Team.RED

    def get_closest_robot(self, position: Vector2D, team: Optional[Team] = None) -> Optional[Robot]:
        """Get closest robot to position, optionally filtered by team."""
        robots = self.get_alive_robots()
        if team:
            robots = [r for r in robots if r.team == team]

        if not robots:
            return None

        closest = min(robots, key=lambda r: r.position.distance_to(position))
        return closest if closest.position.distance_to(position) < 30 else None

    def get_objective_by_type(self, objective_type: ObjectiveType) -> Optional[Objective]:
        """Get the first objective of specified type."""
        for obj in self.objectives:
            if obj.type == objective_type:
                return obj
        return None

    def get_objective_by_team(self, team: Team) -> Optional[Objective]:
        """Get objective assigned to specific team."""
        for obj in self.objectives:
            if obj.team_required == team:
                return obj
        return None

    def update(self, dt: float):
        """Update game state."""
        self.round_time += dt
        current_time = time.time()

        # Update robots
        for robot in self.robots.values():
            if robot.is_alive:
                robot.update_cooldown(dt)

        # Update objectives
        for objective in self.objectives:
            objective.update(self, dt)

        # Update power-ups
        for power_up in self.power_ups[:]:  # Copy list to allow removal
            if power_up.is_expired(current_time):
                self.power_ups.remove(power_up)
                self.add_particle("powerup_disappear", power_up.position, duration=1.0)

        # Update hazards
        for hazard in self.hazards[:]:
            if not hazard.active:
                self.hazards.remove(hazard)
                continue

            # Apply hazard damage to robots
            for robot in self.robots.values():
                if robot.is_alive:
                    damage = hazard.affect_robot(robot)
                    if damage > 0:
                        self.add_audio_event("hazard_damage", robot.position)

        # Update difficulty based on performance
        self.update_difficulty()

        # Check for round end conditions
        self.check_round_end()

    def update_difficulty(self):
        """Adaptive difficulty system based on team performance."""
        red_robots_alive = len(self.get_team_robots(Team.RED))
        blue_robots_alive = len(self.get_team_robots(Team.BLUE))
        red_score = self.scores[Team.RED]
        blue_score = self.scores[Team.BLUE]

        # Calculate imbalance
        if red_robots_alive == 0 and blue_robots_alive > 0:
            # Red team is wiped out
            self.difficulty = min(1.0, self.difficulty + 0.05)
        elif blue_robots_alive == 0 and red_robots_alive > 0:
            # Blue team is wiped out
            self.difficulty = max(0.0, self.difficulty - 0.05)

        # Adjust difficulty based on score difference
        score_diff = abs(red_score - blue_score)
        if score_diff > 50:
            if red_score > blue_score:
                self.difficulty = max(0.0, self.difficulty - 0.02)
            else:
                self.difficulty = min(1.0, self.difficulty + 0.02)

        # Adjust based on how close the game is
        total_alive = red_robots_alive + blue_robots_alive
        if total_alive > 0:
            team_balance = abs(red_robots_alive - blue_robots_alive) / total_alive
            if team_balance > 0.5:  # One team has significantly more robots
                if red_robots_alive > blue_robots_alive:
                    self.difficulty = max(0.0, self.difficulty - 0.01)
                else:
                    self.difficulty = min(1.0, self.difficulty + 0.01)

    def check_round_end(self):
        """Check if round should end."""
        red_robots_alive = len(self.get_team_robots(Team.RED))
        blue_robots_alive = len(self.get_team_robots(Team.BLUE))

        # Check time limit
        if self.round_time >= self.time_limit:
            self.end_round("Time Limit Reached")
            return

        # Check if one team has no robots left
        if red_robots_alive == 0:
            self.end_round("Blue Team Wins - All Red Robots Eliminated")
            return
        elif blue_robots_alive == 0:
            self.end_round("Red Team Wins - All Blue Robots Eliminated")
            return

        # Check if objective completed
        for objective in self.objectives:
            if objective.progress >= objective.max_progress:
                if objective.captured_by:
                    self.end_round(f"{objective.captured_by.value} Team Wins - {objective.type.value} Completed")
                    return

    def end_round(self, reason: str):
        """End the current round."""
        self.battle_log.append(f"ROUND END: {reason}")

        # Calculate final scores
        red_robots = len(self.get_team_robots(Team.RED))
        blue_robots = len(self.get_team_robots(Team.BLUE))

        # Award points for surviving robots
        self.scores[Team.RED] += red_robots * 10
        self.scores[Team.BLUE] += blue_robots * 10

        # Award points for objectives
        for objective in self.objectives:
            if objective.captured_by:
                self.scores[objective.captured_by] += 50

        # Log final scores
        self.battle_log.append(f"Final Scores - Red: {self.scores[Team.RED]}, Blue: {self.scores[Team.BLUE]}")

        # Trigger AI learning from this round
        self.learns_from_battle()

    def learns_from_battle(self):
        """AI learning feedback loop: robots analyze performance and adapt strategies."""
        for robot in self.robots.values():
            if not robot.is_alive:
                continue

            # Analyze performance
            # Calculate success rate based on kills, assists, objective contributions
            kills = len([r for r in self.robots.values() 
                        if not r.is_alive and r.id in robot.strategy_history])
            assists = len([r for r in self.robots.values() 
                         if r.team == robot.team and r.id in robot.strategy_history])

            # Calculate team contribution
            team_robots = len(self.get_team_robots(robot.team))
            if team_robots > 0:
                team_contribution = len([r for r in self.get_team_robots(robot.team) 
                                       if r.id != robot.id and r.is_alive]) / team_robots
            else:
                team_contribution = 0

            # Update knowledge base with learning
            if not robot.knowledge_base:
                robot.knowledge_base = {
                    "success_rate": 0.0,
                    "teamwork_score": 0.0,
                    "preferred_strategy": "default",
                    "experience": 0
                }

            # Update success rate (0-1 scale)
            robot.knowledge_base["experience"] += 1
            success_rate = (kills + assists * 0.5) / max(robot.knowledge_base["experience"], 1)
            robot.knowledge_base["success_rate"] = (robot.knowledge_base.get("success_rate", 0) * 0.7 + success_rate * 0.3)

            # Update teamwork score
            robot.knowledge_base["teamwork_score"] = (robot.knowledge_base.get("teamwork_score", 0) * 0.7 + team_contribution * 0.3)

            # Adapt strategy based on performance
            if robot.knowledge_base["success_rate"] > 0.8:
                robot.knowledge_base["preferred_strategy"] = "aggressive"
            elif robot.knowledge_base["teamwork_score"] > 0.8:
                robot.knowledge_base["preferred_strategy"] = "support"
            elif robot.knowledge_base["success_rate"] < 0.3:
                robot.knowledge_base["preferred_strategy"] = "defensive"

            # Update robot characteristics based on learning
            if robot.knowledge_base["preferred_strategy"] == "aggressive":
                robot.speed = min(1.4, robot.speed + self.bot_learning_factor * 0.1)
                robot.weapon = random.choice([WeaponType.RIFLE, WeaponType.SNIPER, WeaponType.LAUNCHER])
                robot.recharge_rate = min(0.08, robot.recharge_rate + self.bot_learning_factor * 0.01)
            elif robot.knowledge_base["preferred_strategy"] == "support":
                robot.max_health = max(120, robot.max_health + self.bot_learning_factor * 5)
                robot.weapon = WeaponType.HEALING_GUN
                robot.recharge_rate = min(0.08, robot.recharge_rate + self.bot_learning_factor * 0.01)
            elif robot.knowledge_base["preferred_strategy"] == "defensive":
                robot.armor = min(50, robot.armor + self.bot_learning_factor * 3)
                robot.speed = max(0.8, robot.speed - self.bot_learning_factor * 0.05)
                robot.weapon = WeaponType.SHOTGUN

            # Reset cooldown for next round
            robot.weapon_cooldown = 0
            robot.energy = robot.max_energy

    def add_particle(self, particle_type: str, position: Vector2D, duration: float = 1.0, color: str = "white"):
        """Add a visual particle effect."""
        self.particles.append({
            "type": particle_type,
            "position": position,
            "duration": duration,
            "start_time": time.time(),
            "color": color
        })

    def add_audio_event(self, event_type: str, position: Vector2D, volume: float = 1.0):
        """Add an audio event."""
        self.audio_events.append({
            "type": event_type,
            "position": position,
            "volume": volume,
            "time": time.time()
        })

    def get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
