    def update_difficulty(self):
        """Adaptive difficulty system based on team performance."""
        red_robots_alive = len(self.get_team_robots(Team.RED))
        blue_robots_alive = len(self.get_team_robots(Team.BLUE))
        red_score = self.scores[Team.RED]
        blue_score = self.scores[Team.BLUE]

        # Calculate imbalance
        if red_robots_alive == 0 and blue_robots_alive > 0:
            # Red team is wiped out
            self.difficulty = min(1.0, self.difficulty + 0.05)
        elif blue_robots_alive == 0 and red_robots_alive > 0:
            # Blue team is wiped out
            self.difficulty = max(0.0, self.difficulty - 0.05)

        # Adjust difficulty based on score difference
        score_diff = abs(red_score - blue_score)
        if score_diff > 50:
            if red_score > blue_score:
                self.difficulty = max(0.0, self.difficulty - 0.02)
            else:
                self.difficulty = min(1.0, self.difficulty + 0.02)

        # Adjust based on how close the game is
        total_alive = red_robots_alive + blue_robots_alive
        if total_alive > 0:
            team_balance = abs(red_robots_alive - blue_robots_alive) / total_alive
            if team_balance > 0.5:  # One team has significantly more robots
                if red_robots_alive > blue_robots_alive:
