            success_rate = (kills + assists * 0.5) / max(robot.knowledge_base["experience"], 1)
            robot.knowledge_base["success_rate"] = (robot.knowledge_base.get("success_rate", 0) * 0.7 + success_rate * 0.3)

            # Update teamwork score
            robot.knowledge_base["teamwork_score"] = (robot.knowledge_base.get("teamwork_score", 0) * 0.7 + team_contribution * 0.3)

            # Adapt strategy based on performance
            if robot.knowledge_base["success_rate"] > 0.8:
                robot.knowledge_base["preferred_strategy"] = "aggressive"
            elif robot.knowledge_base["teamwork_score"] > 0.8:
                robot.knowledge_base["preferred_strategy"] = "support"
            elif robot.knowledge_base["success_rate"] < 0.3:
                robot.knowledge_base["preferred_strategy"] = "defensive"

