class RobotAI:
    """AI controller for robots in CyberArena."""

    def __init__(self, robot_id: str, game_state: GameState):
        self.robot_id = robot_id
        self.game_state = game_state
        self.last_decision_time = 0
        self.decision_cooldown = 0.5  # Seconds between decisions
        self.current_target = None
        self.current_objective = None
        self.role = "default"
        self.threat_level = 0.0
        self.last_known_enemy_positions = []

    def update(self, dt: float) -> Dict[str, Any]:
        """Update AI decision making."""
        current_time = time.time()
        if current_time - self.last_decision_time < self.decision_cooldown:
            return {}

        self.last_decision_time = current_time

        robot = self.game_state.get_robot_by_id(self.robot_id)
        if not robot or not robot.is_alive:
            return {}

        # Determine role based on strategy and team composition
        self.determine_role(robot)

        # Update threat level based on nearby enemies
        self.update_threat_level(robot)

        # Choose action based on role and situation
        action = self.choose_action(robot)

        # Return action for game engine to execute
        return action

    def determine_role(self, robot: Robot):
        """Dynamically assign role based on team needs and robot capabilities."""
        team_robots = self.game_state.get_team_robots(robot.team)
        alive_team_robots = [r for r in team_robots if r.is_alive]

        if len(alive_team_robots) == 0:
            return

        # Count roles
        assault_count = len([r for r in alive_team_robots if r.robot_type == RobotType.ASSAULT])
        support_count = len([r for r in alive_team_robots if r.robot_type == RobotType.SUPPORT])
        recon_count = len([r for r in alive_team_robots if r.robot_type == RobotType.RECON])
        tank_count = len([r for r in alive_team_robots if r.robot_type == RobotType.TANK])

        # Use knowledge base to determine preferred strategy
        preferred_strategy = robot.knowledge_base.get("preferred_strategy", "default")

        # Check team balance
        if preferred_strategy == "aggressive":
            robot.role = "assault"
        elif preferred_strategy == "support":
            robot.role = "support"
        elif preferred_strategy == "defensive":
            robot.role = "tank"
        else:
            # Auto-balance roles based on team needs
            if support_count == 0:
                robot.role = "support"
            elif assault_count == 0:
                robot.role = "assault"
            elif recon_count == 0:
                robot.role = "recon"
            elif tank_count == 0:
                robot.role = "tank"
            else:
                # Default: assign based on robot type
                robot.role = robot.robot_type.value.lower()

    def update_threat_level(self, robot: Robot):
        """Update threat level based on nearby enemies."""
        self.threat_level = 0.0

        # Check distance to enemies
        for other_robot in self.game_state.get_alive_robots():
            if other_robot.team != robot.team and other_robot.is_alive:
                distance = robot.position.distance_to(other_robot.position)
                if distance < 20:
                    # Higher threat for closer enemies
                    threat = (20 - distance) / 20
                    # Higher threat for high-damage weapons
                    weapon_damage = {
                        WeaponType.SNIPER: 1.5,
                        WeaponType.LAUNCHER: 1.8,
                        WeaponType.SHOTGUN: 1.2,
                        WeaponType.RIFLE: 1.0,
                        WeaponType.MELEE: 1.3,
                        WeaponType.HEALING_GUN: 0.5
                    }
                    weapon_factor = weapon_damage.get(other_robot.weapon, 1.0)
                    self.threat_level += threat * weapon_factor

        # Cap threat level
        self.threat_level = min(self.threat_level, 1.0)

    def choose_action(self, robot: Robot) -> Dict[str, Any]:
        """Choose the best action for the robot based on current situation."""
        # Get objectives
        objectives = self.game_state.objectives
        current_objective = None

        # Find objective for team
        for obj in objectives:
            if obj.team_required == robot.team:
                current_objective = obj
                break

        # Check if there's an enemy nearby
        target_robot = self.find_target(robot)
        if target_robot:
            distance = robot.position.distance_to(target_robot.position)

            # If close enough for melee, use melee
            if distance < 3 and robot.weapon != WeaponType.MELEE and robot.can_attack():
                return self.create_attack_action(target_robot.position, WeaponType.MELEE)

            # If enemy is at range and we have a ranged weapon, attack
            if distance < 40 and robot.can_attack():
                return self.create_attack_action(target_robot.position, robot.weapon)

        # If no immediate target, look for objectives
        if current_objective and current_objective.type == ObjectiveType.CAPTURE_FLAG:
            # Move toward flag if not captured
            if not current_objective.captured_by or current_objective.captured_by != robot.team:
                return self.create_move_action(current_objective.position)

        elif current_objective and current_objective.type == ObjectiveType.ESCAPE_PAYLOAD:
            # Escort payload
            if current_objective.captured_by == robot.team:
                # Find payload and follow it
                payload_distance = robot.position.distance_to(current_objective.position)
                if payload_distance > 5:
                    return self.create_move_action(current_objective.position)
                else:
                    # Follow the payload's next target
                    if current_objective.current_target_index < len(current_objective.escort_targets):
                        target = current_objective.escort_targets[current_objective.current_target_index]
                        return self.create_move_action(target)

        elif current_objective and current_objective.type == ObjectiveType.DEFEND_BASE:
            # Defend position
            return self.create_move_action(current_objective.position)

        # If no specific objective, look for power-ups
        if len(self.game_state.power_ups) > 0:
            closest_powerup = min(self.game_state.power_ups, 
                                 key=lambda p: robot.position.distance_to(p.position))
            if robot.position.distance_to(closest_powerup.position) < 15:
                return self.create_move_action(closest_powerup.position)

        # If we're low on health, look for healing
        if robot.health < 30:
            # Find teammate with healing gun
            for teammate in self.game_state.get_team_robots(robot.team):
                if teammate.is_alive and teammate.weapon == WeaponType.HEALING_GUN:
                    if teammate.position.distance_to(robot.position) < 10:
                        return self.create_move_action(teammate.position)

        # If no specific target, patrol or stay in position
        return self.create_patrol_action(robot)

    def create_attack_action(self, target_position: Vector2D, weapon_type: WeaponType) -> Dict[str, Any]:
        """Return attack action."""
        return {
            "action": "attack",
            "target_position": target_position,
            "weapon": weapon_type
        }

    def create_move_action(self, target_position: Vector2D) -> Dict[str, Any]:
        """Return move action."""
        return {
            "action": "move",
            "target_position": target_position
        }

    def create_patrol_action(self, robot: Robot) -> Dict[str, Any]:
        """Return patrol action."""
        # Patrol around spawn point or objective
        # Use knowledge base to determine patrol pattern
        if robot.knowledge_base.get("preferred_strategy") == "defensive":
            # Defenders patrol near base
            for obj in self.game_state.objectives:
                if obj.team_required == robot.team and obj.type == ObjectiveType.DEFEND_BASE:
                    # Patrol around base
                    angle = (time.time() % 10) / 10 * 2 * math.pi
                    patrol_offset = Vector2D(math.cos(angle) * 8, math.sin(angle) * 8)
                    patrol_target = obj.position + patrol_offset
                    return self.create_move_action(patrol_target)

        # Random patrol pattern
        base_position = robot.position
        angle = (time.time() % 15) / 15 * 2 * math.pi
        patrol_offset = Vector2D(math.cos(angle) * 10, math.sin(angle) * 10)
        patrol_target = base_position + patrol_offset
        return self.create_move_action(patrol_target)

    def find_target(self, robot: Robot) -> Optional[Robot]:
        """Find the most urgent target."""
        enemies = [r for r in self.game_state.get_alive_robots() if r.team != robot.team]
        if not enemies:
            return None

        # Prioritize targets based on threat and health
        def target_priority(enemy: Robot):
            # Higher priority for low health (easier to kill)
            health_factor = 1.0 - (enemy.health / enemy.max_health)
            # Higher priority for high damage weapons
            weapon_factor = {
                WeaponType.SNIPER: 1.5,
                WeaponType.LAUNCHER: 1.8,
                WeaponType.SHOTGUN: 1.2,
                WeaponType.RIFLE: 1.0,
                WeaponType.MELEE: 1.3,
                WeaponType.HEALING_GUN: 0.5
            }.get(enemy.weapon, 1.0)
            # Higher priority for closer enemies
            distance = robot.position.distance_to(enemy.position)
            distance_factor = 1.0 / (1.0 + distance / 10)

            # Combine factors
            return health_factor * 0.4 + weapon_factor * 0.3 + distance_factor * 0.3

        # Return enemy with highest priority
        return max(enemies, key=target_priority)

