    weapon: WeaponType = WeaponType.RIFLE
    weapon_cooldown: float = 0.0
    recharge_rate: float = 0.05
    energy: float = 100.0
    max_energy: float = 100.0
    is_alive: bool = True
    last_action: str = "idle"
    target: Optional[str] = None
    role: str = "default"
    knowledge_base: Dict = field(default_factory=dict)
    strategy_history: List = field(default_factory=list)

    def take_damage(self, damage: float) -> float:
        """Apply damage to robot, considering armor."""
        effective_damage = damage * (1 - min(self.armor / 100, 0.75))
        self.health -= effective_damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
        return effective_damage

    def heal(self, amount: float) -> float:
        """Heal robot, up to max health."""
        heal_amount = min(amount, self.max_health - self.health)
        self.health += heal_amount
        return heal_amount

    def recharge_energy(self, amount: float) -> float:
        """Recharge robot's energy, up to max energy."""
        recharge_amount = min(amount, self.max_energy - self.energy)
        self.energy += recharge_amount
        return recharge_amount

    def update_cooldown(self, dt: float):
        """Update weapon cooldown."""
        if self.weapon_cooldown > 0:
            self.weapon_cooldown -= dt

    def can_attack(self) -> bool:
        """Check if robot is ready to attack."""
        return self.weapon_cooldown <= 0 and self.is_alive and self.energy >= 10

    def use_weapon(self, target_position: Vector2D, game_state: 'GameState') -> Dict:
        """Use current weapon and return attack results."""
        if not self.can_attack():
            return {"success": False, "damage": 0, "energy_used": 0, "effect": None}

        # Calculate energy cost based on weapon
        energy_costs = {
            WeaponType.RIFLE: 10,
            WeaponType.SHOTGUN: 15,
            WeaponType.SNIPER: 25,
            WeaponType.LAUNCHER: 35,
            WeaponType.MELEE: 5,
            WeaponType.HEALING_GUN: 20
        }

        damage_values = {
            WeaponType.RIFLE: 15,
            WeaponType.SHOTGUN: 30,
            WeaponType.SNIPER: 50,
            WeaponType.LAUNCHER: 70,
            WeaponType.MELEE: 40,
            WeaponType.HEALING_GUN: 0
        }

        cooldowns = {
            WeaponType.RIFLE: 0.5,
            WeaponType.SHOTGUN: 1.0,
            WeaponType.SNIPER: 2.0,
            WeaponType.LAUNCHER: 3.0,
            WeaponType.MELEE: 0.8,
            WeaponType.HEALING_GUN: 1.5
        }

        energy_cost = energy_costs.get(self.weapon, 10)
        damage = damage_values.get(self.weapon, 15)
        cooldown = cooldowns.get(self.weapon, 0.5)

        if self.energy < energy_cost:
            return {"success": False, "damage": 0, "energy_used": 0, "effect": None}

        self.energy -= energy_cost
        self.weapon_cooldown = cooldown
        self.last_action = "attack"

        # Calculate distance to target
        distance = self.position.distance_to(target_position)

        # Adjust damage based on distance for ranged weapons
        if self.weapon in [WeaponType.RIFLE, WeaponType.SHOTGUN, WeaponType.SNIPER, WeaponType.LAUNCHER]:
            if distance > 50:
                damage *= 0.5  # Reduced damage at long range
            elif distance > 30:
                damage *= 0.75

        # For melee, only work if very close
        if self.weapon == WeaponType.MELEE and distance > 3:
            return {"success": False, "damage": 0, "energy_used": energy_cost, "effect": None}

        # Find target robot
        target_robot = None
        for robot in game_state.robots.values():
            if robot.is_alive and robot.position.distance_to(target_position) < 2:
                target_robot = robot
                break

        if target_robot is None:
            return {"success": False, "damage": 0, "energy_used": energy_cost, "effect": None}

        # Apply damage
        actual_damage = target_robot.take_damage(damage)

        # Apply special effects
        effect = None
        if self.weapon == WeaponType.HEALING_GUN:
            target_robot.heal(damage)
            effect = "heal"
        elif self.weapon == WeaponType.LAUNCHER:
            effect = "explosion"

        return {
            "success": True,
            "damage": actual_damage,
            "energy_used": energy_cost,
            "effect": effect,
            "target_id": target_robot.id
        }

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def is_expired(self, current_time: float) -> bool:
        return current_time - self.spawn_time > self.duration

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float = 5.0
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())

    def affect_robot(self, robot: Robot) -> float:
        """Apply hazard effect to robot and return damage."""
        if not self.active or not robot.is_alive:
            return 0

        distance = robot.position.distance_to(self.position)
        if distance <= self.radius:
            # Apply damage based on proximity (more damage when closer)
            damage_multiplier = 1.0 - (distance / self.radius)
            damage = self.damage_per_second * damage_multiplier
            robot.take_damage(damage)
            return damage
        return 0

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    progress: float = 0.0
    max_progress: float = 100.0
    team_required: Optional[Team] = None
    captured_by: Optional[Team] = None
    defenders: List[str] = field(default_factory=list)
    escort_targets: List[Vector2D] = field(default_factory=list)
    current_target_index: int = 0

    def update(self, game_state: 'GameState', dt: float):
        """Update objective progress based on game state."""
        if self.type == ObjectiveType.CAPTURE_FLAG:
            # Count robots from required team near flag
            nearby_robots = 0
            for robot in game_state.robots.values():
                if (robot.is_alive and robot.team == self.team_required and 
                    robot.position.distance_to(self.position) < 5):
                    nearby_robots += 1

            # Progress increases with more robots nearby
            if nearby_robots > 0:
                self.progress += nearby_robots * dt * 5
                if self.progress >= self.max_progress:
                    self.progress = self.max_progress
                    self.captured_by = self.team_required
            else:
                # Reduce progress if no team members nearby
                if self.captured_by and self.captured_by != self.team_required:
                    self.progress -= dt * 2
                    if self.progress <= 0:
                        self.captured_by = None

        elif self.type == ObjectiveType.ESCAPE_PAYLOAD:
            # Find robot escorting payload
            escorting_robot = None
            for robot in game_state.robots.values():
                if (robot.is_alive and robot.team == self.team_required and elif self.type == ObjectiveType.ESCORT_PAYLOAD:                    escorting_robot = robot
                    break

            if escorting_robot:
                # Move payload toward next target
                if self.current_target_index < len(self.escort_targets):
                    target = self.escort_targets[self.current_target_index]
                    direction = (target - self.position).normalize()
                    self.position = self.position + direction * dt * 10

                    # Check if reached target
                    if self.position.distance_to(target) < 2:
                        self.current_target_index += 1
                        if self.current_target_index >= len(self.escort_targets):
                            self.progress = 100
                self.progress += dt * 2
            else:
                # Payload slows if not escorted
                self.progress += dt * 0.5

@dataclass
class GameState:
    """Contains all game state information."""
    robots: Dict[str, Robot] = field(default_factory=dict)
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    scores: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    round_time: float = 0.0
    game_mode: str = "Capture the Flag"
    time_limit: float = 300.0  # 5 minutes
    spawn_points: Dict[Team, List[Vector2D]] = field(default_factory=dict)
    team_size: int = 4
    difficulty: float = 0.5  # 0.0 to 1.0, 0.5 is medium
    last_update: float = field(default_factory=time.time)
    bot_learning_factor: float = 0.1  # How much bots learn from experience
    battle_log: List[str] = field(default_factory=list)
    particles: List[Dict] = field(default_factory=list)  # For visual effects
    audio_events: List[Dict] = field(default_factory=list)  # For audio effects

    def add_robot(self, robot: Robot):
        self.robots[robot.id] = robot
        if robot.team not in self.spawn_points:
            self.spawn_points[robot.team] = []

    def get_team_robots(self, team: Team) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.team == team and robot.is_alive]

    def get_alive_robots(self) -> List[Robot]:
        return [robot for robot in self.robots.values() if robot.is_alive]

    def get_opposing_team(self, team: Team) -> Team:
        return Team.BLUE if team == Team.RED else Team.RED

    def get_closest_robot(self, position: Vector2D, team: Optional[Team] = None) -> Optional[Robot]:
        """Get closest robot to position, optionally filtered by team."""
        robots = self.get_alive_robots()
        if team:
            robots = [r for r in robots if r.team == team]

        if not robots:
            return None

        closest = min(robots, key=lambda r: r.position.distance_to(position))
        return closest if closest.position.distance_to(position) < 30 else None

    def get_objective_by_type(self, objective_type: ObjectiveType) -> Optional[Objective]:
        """Get the first objective of specified type."""
        for obj in self.objectives:
            if obj.type == objective_type:
                return obj
        return None

    def get_objective_by_team(self, team: Team) -> Optional[Objective]:
        """Get objective assigned to specific team."""
        for obj in self.objectives:
            if obj.team_required == team:
                return obj
        return None

    def update(self, dt: float):
        """Update game state."""
        self.round_time += dt
        current_time = time.time()

        # Update robots
        for robot in self.robots.values():
            if robot.is_alive:
                robot.update_cooldown(dt)

        # Update objectives
        for objective in self.objectives:
            objective.update(self, dt)

        # Update power-ups
        for power_up in self.power_ups[:]:  # Copy list to allow removal
            if power_up.is_expired(current_time):
                self.power_ups.remove(power_up)
                self.add_particle("powerup_disappear", power_up.position, duration=1.0)

        # Update hazards
        for hazard in self.hazards[:]:
            if not hazard.active:
                self.hazards.remove(hazard)
                continue

            # Apply hazard damage to robots
            for robot in self.robots.values():
                if robot.is_alive:
                    damage = hazard.affect_robot(robot)
                    if damage > 0:
                        self.add_audio_event("hazard_damage", robot.position)

        # Update difficulty based on performance
        self.update_difficulty()

        # Check for round end conditions
        self.check_round_end()

    def update_difficulty(self):
        """Adaptive difficulty system based on team performance."""
        red_robots_alive = len(self.get_team_robots(Team.RED))
        blue_robots_alive = len(self.get_team_robots(Team.BLUE))
        red_score = self.scores[Team.RED]
        blue_score = self.scores[Team.BLUE]

        # Calculate imbalance
        if red_robots_alive == 0 and blue_robots_alive > 0:
            # Red team is wiped out
            self.difficulty = min(1.0, self.difficulty + 0.05)
        elif blue_robots_alive == 0 and red_robots_alive > 0:
            # Blue team is wiped out
            self.difficulty = max(0.0, self.difficulty - 0.05)

        # Adjust difficulty based on score difference
        score_diff = abs(red_score - blue_score)
        if score_diff > 50:
            if red_score > blue_score:
                self.difficulty = max(0.0, self.difficulty - 0.02)
            else:
                self.difficulty = min(1.0, self.difficulty + 0.02)

        # Adjust based on how close the game is
        total_alive = red_robots_alive + blue_robots_alive
        if total_alive > 0:
            team_balance = abs(red_robots_alive - blue_robots_alive) / total_alive
            if team_balance > 0.5:  # One team has significantly more robots
                if red_robots_alive > blue_robots_alive:
                    self.difficulty = max(0.0, self.difficulty - 0.01)
                else:
                    self.difficulty = min(1.0, self.difficulty + 0.01)

    def check_round_end(self):
        """Check if round should end."""
        red_robots_alive = len(self.get_team_robots(Team.RED))
        blue_robots_alive = len(self.get_team_robots(Team.BLUE))

        # Check time limit
        if self.round_time >= self.time_limit:
            self.end_round("Time Limit Reached")
            return

        # Check if one team has no robots left
        if red_robots_alive == 0:
            self.end_round("Blue Team Wins - All Red Robots Eliminated")
            return
        elif blue_robots_alive == 0:
            self.end_round("Red Team Wins - All Blue Robots Eliminated")
            return

        # Check if objective completed
        for objective in self.objectives:
            if objective.progress >= objective.max_progress:
                if objective.captured_by:
                    self.end_round(f"{objective.captured_by.value} Team Wins - {objective.type.value} Completed")
                    return

    def end_round(self, reason: str):
        """End the current round."""
        self.battle_log.append(f"ROUND END: {reason}")

        # Calculate final scores
        red_robots = len(self.get_team_robots(Team.RED))
        blue_robots = len(self.get_team_robots(Team.BLUE))

        # Award points for surviving robots
        self.scores[Team.RED] += red_robots * 10
        self.scores[Team.BLUE] += blue_robots * 10

        # Award points for objectives
        for objective in self.objectives:
            if objective.captured_by:
                self.scores[objective.captured_by] += 50

        # Log final scores
        self.battle_log.append(f"Final Scores - Red: {self.scores[Team.RED]}, Blue: {self.scores[Team.BLUE]}")

        # Trigger AI learning from this round
        self.learns_from_battle()

    def learns_from_battle(self):
        """AI learning feedback loop: robots analyze performance and adapt strategies."""
        for robot in self.robots.values():
            if not robot.is_alive:
                continue

            # Analyze performance
            # Calculate success rate based on kills, assists, objective contributions
            kills = len([r for r in self.robots.values() 
                        if not r.is_alive and r.id in robot.strategy_history])
            assists = len([r for r in self.robots.values() 
                         if r.team == robot.team and r.id in robot.strategy_history])

            # Calculate team contribution
            team_robots = len(self.get_team_robots(robot.team))
            if team_robots > 0:
                team_contribution = len([r for r in self.get_team_robots(robot.team) 
                                       if r.id != robot.id and r.is_alive]) / team_robots
            else:
                team_contribution = 0

            # Update knowledge base with learning
            if not robot.knowledge_base:
                robot.knowledge_base = {
                    "success_rate": 0.0,
                    "teamwork_score": 0.0,
                    "preferred_strategy": "default",
                    "experience": 0
                }

            # Update success rate (0-1 scale)
            robot.knowledge_base["experience"] += 1
            success_rate = (kills + assists * 0.5) / max(robot.knowledge_base["experience"], 1)
            robot.knowledge_base["success_rate"] = (robot.knowledge_base.get("success_rate", 0) * 0.7 + success_rate * 0.3)

            # Update teamwork score
            robot.knowledge_base["teamwork_score"] = (robot.knowledge_base.get("teamwork_score", 0) * 0.7 + team_contribution * 0.3)

            # Adapt strategy based on performance
            if robot.knowledge_base["success_rate"] > 0.8:
                robot.knowledge_base["preferred_strategy"] = "aggressive"
            elif robot.knowledge_base["teamwork_score"] > 0.8:
                robot.knowledge_base["preferred_strategy"] = "support"
            elif robot.knowledge_base["success_rate"] < 0.3:
                robot.knowledge_base["preferred_strategy"] = "defensive"

            # Update robot characteristics based on learning
            if robot.knowledge_base["preferred_strategy"] == "aggressive":
                robot.speed = min(1.4, robot.speed + self.bot_learning_factor * 0.1)
                robot.weapon = random.choice([WeaponType.RIFLE, WeaponType.SNIPER, WeaponType.LAUNCHER])
                robot.recharge_rate = min(0.08, robot.recharge_rate + self.bot_learning_factor * 0.01)
            elif robot.knowledge_base["preferred_strategy"] == "support":
                robot.max_health = max(120, robot.max_health + self.bot_learning_factor * 5)
                robot.weapon = WeaponType.HEALING_GUN
                robot.recharge_rate = min(0.08, robot.recharge_rate + self.bot_learning_factor * 0.01)
            elif robot.knowledge_base["preferred_strategy"] == "defensive":
                robot.armor = min(50, robot.armor + self.bot_learning_factor * 3)
                robot.speed = max(0.8, robot.speed - self.bot_learning_factor * 0.05)
                robot.weapon = WeaponType.SHOTGUN

            # Reset cooldown for next round
            robot.weapon_cooldown = 0
            robot.energy = robot.max_energy

    def add_particle(self, particle_type: str, position: Vector2D, duration: float = 1.0, color: str = "white"):
        """Add a visual particle effect."""
        self.particles.append({
            "type": particle_type,
            "position": position,
            "duration": duration,
            "start_time": time.time(),
            "color": color
        })

    def add_audio_event(self, event_type: str, position: Vector2D, volume: float = 1.0):
        """Add an audio event."""
        self.audio_events.append({
            "type": event_type,
            "position": position,
            "volume": volume,
            "time": time.time()
        })

    def get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
        """Get robot by ID."""
        return self.robots.get(robot_id)

# ==============================
# AI BEHAVIOR SYSTEM
# ==============================

class RobotAI:
    """AI controller for robots in CyberArena."""

    def __init__(self, robot_id: str, game_state: GameState):
        self.robot_id = robot_id
        self.game_state = game_state
        self.last_decision_time = 0
        self.decision_cooldown = 0.5  # Seconds between decisions
        self.current_target = None
        self.current_objective = None
        self.role = "default"
        self.threat_level = 0.0
        self.last_known_enemy_positions = []

    def update(self, dt: float) -> Dict[str, Any]:
        """Update AI decision making."""
        current_time = time.time()
        if current_time - self.last_decision_time < self.decision_cooldown:
            return {}

        self.last_decision_time = current_time

        robot = self.game_state.get_robot_by_id(self.robot_id)
        if not robot or not robot.is_alive:
            return {}

        # Determine role based on strategy and team composition
        self.determine_role(robot)

        # Update threat level based on nearby enemies
        self.update_threat_level(robot)

        # Choose action based on role and situation
        action = self.choose_action(robot)

        # Return action for game engine to execute
        return action

    def determine_role(self, robot: Robot):
        """Dynamically assign role based on team needs and robot capabilities."""
        team_robots = self.game_state.get_team_robots(robot.team)
        alive_team_robots = [r for r in team_robots if r.is_alive]

        if len(alive_team_robots) == 0:
            return

        # Count roles
        assault_count = len([r for r in alive_team_robots if r.robot_type == RobotType.ASSAULT])
        support_count = len([r for r in alive_team_robots if r.robot_type == RobotType.SUPPORT])
        recon_count = len([r for r in alive_team_robots if r.robot_type == RobotType.RECON])
        tank_count = len([r for r in alive_team_robots if r.robot_type == RobotType.TANK])

        # Use knowledge base to determine preferred strategy
        preferred_strategy = robot.knowledge_base.get("preferred_strategy", "default")

        # Check team balance
        if preferred_strategy == "aggressive":
            robot.role = "assault"
        elif preferred_strategy == "support":
            robot.role = "support"
        elif preferred_strategy == "defensive":
            robot.role = "tank"
        else:
            # Auto-balance roles based on team needs
            if support_count == 0:
                robot.role = "support"
            elif assault_count == 0:
                robot.role = "assault"
            elif recon_count == 0:
                robot.role = "recon"
            elif tank_count == 0:
                robot.role = "tank"
            else:
                # Default: assign based on robot type
                robot.role = robot.robot_type.value.lower()

    def update_threat_level(self, robot: Robot):
        """Update threat level based on nearby enemies."""
        self.threat_level = 0.0

        # Check distance to enemies
        for other_robot in self.game_state.get_alive_robots():
            if other_robot.team != robot.team and other_robot.is_alive:
                distance = robot.position.distance_to(other_robot.position)
                if distance < 20:
                    # Higher threat for closer enemies
                    threat = (20 - distance) / 20
                    # Higher threat for high-damage weapons
                    weapon_damage = {
                        WeaponType.SNIPER: 1.5,
                        WeaponType.LAUNCHER: 1.8,
                        WeaponType.SHOTGUN: 1.2,
                        WeaponType.RIFLE: 1.0,
                        WeaponType.MELEE: 1.3,
                        WeaponType.HEALING_GUN: 0.5
                    }
                    weapon_factor = weapon_damage.get(other_robot.weapon, 1.0)
                    self.threat_level += threat * weapon_factor

        # Cap threat level
        self.threat_level = min(self.threat_level, 1.0)

    def choose_action(self, robot: Robot) -> Dict[str, Any]:
        """Choose the best action for the robot based on current situation."""
        # Get objectives
        objectives = self.game_state.objectives
        current_objective = None

        # Find objective for team
        for obj in objectives:
            if obj.team_required == robot.team:
                current_objective = obj
                break

        # Check if there's an enemy nearby
        target_robot = self.find_target(robot)
        if target_robot:
            distance = robot.position.distance_to(target_robot.position)

            # If close enough for melee, use melee
            if distance < 3 and robot.weapon != WeaponType.MELEE and robot.can_attack():
                return self.create_attack_action(target_robot.position, WeaponType.MELEE)

            # If enemy is at range and we have a ranged weapon, attack
            if distance < 40 and robot.can_attack():
                return self.create_attack_action(target_robot.position, robot.weapon)

        # If no immediate target, look for objectives
        if current_objective and current_objective.type == ObjectiveType.CAPTURE_FLAG:
            # Move toward flag if not captured
            if not current_objective.captured_by or current_objective.captured_by != robot.team:
                return self.create_move_action(current_objective.position)

        elif current_objective and current_objective.type == ObjectiveType.ESCAPE_PAYLOAD:
            # Escort payload
            if current_objective.captured_by == robot.team:
                # Find payload and follow it
                payload_distance = robot.position.distance_to(current_objective.position)
                if payload_distance > 5:
                    return self.create_move_action(current_objective.position)
                else:
                    # Follow the payload's next target
                    if current_objective.current_target_index < len(current_objective.escort_targets):
                        target = current_objective.escort_targets[current_objective.current_target_index]
                        return self.create_move_action(target)

        elif current_objective and current_objective.type == ObjectiveType.DEFEND_BASE:
            # Defend position
            return self.create_move_action(current_objective.position)

        # If no specific objective, look for power-ups
        if len(self.game_state.power_ups) > 0:
            closest_powerup = min(self.game_state.power_ups, 
                                 key=lambda p: robot.position.distance_to(p.position))
            if robot.position.distance_to(closest_powerup.position) < 15:
                return self.create_move_action(closest_powerup.position)

        # If we're low on health, look for healing
        if robot.health < 30:
            # Find teammate with healing gun
            for teammate in self.game_state.get_team_robots(robot.team):
                if teammate.is_alive and teammate.weapon == WeaponType.HEALING_GUN:
                    if teammate.position.distance_to(robot.position) < 10:
