@dataclass
class Vector2D:
    """2D vector for position, velocity, and direction"""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def length(self):
        return math.sqrt(self.x * self.x + self.y * self.y)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return self / length

    def distance_to(self, other):
        return (self - other).length()

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def as_tuple(self):
        return (self.x, self.y)

    def copy(self):
        return Vector2D(self.x, self.y)

@dataclass
class Robot:
    """Represents a single AI-controlled robot in the arena"""
    id: str
    team: str
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 150.0
    armor: float = 0.0
    weapon: Optional['Weapon'] = None
    role: str = "attacker"
    last_action_time: float = 0.0
    cooldowns: Dict[str, float] = field(default_factory=dict)
    vision_range: float = 300.0
    team_vision_range: float = 500.0
    objectives: List[str] = field(default_factory=list)
    memory: Dict[str, Any] = field(default_factory=dict)
    stats: Dict[str, int] = field(default_factory=lambda: {"kills": 0, "assists": 0, "objectives": 0, "deaths": 0})
