    def __post_init__(self):
        """Initialize robot after dataclass creation"""
        self.cooldowns = {key: 0.0 for key in ["attack", "ability", "teleport", "shield"]}
        self.power_ups = {powerup: 0.0 for powerup in PowerUpType}
        self.memory["recent_positions"] = deque(maxlen=10)
        self.memory["enemy_positions"] = {}
        self.memory["team_positions"] = {}
        self.memory["objective_history"] = []
        self.memory["battle_outcomes"] = []
        self.color = self._get_team_color()

    def _get_team_color(self) -> Tuple[int, int, int]:
        """Get RGB color based on team"""
        if self.team == TEAM_BLUE:
            return (30, 144, 255)
        elif self.team == TEAM_RED:
            return (255, 60, 60)
        else:
            return (200, 200, 200)

    def apply_power_up(self, power_up_type: PowerUpType, duration: float):
        """Apply a power-up effect to the robot"""
        self.power_ups[power_up_type] = duration
        if power_up_type == PowerUpType.SPEED:
            self.speed *= 1.5
        elif power_up_type == PowerUpType.SHIELD:
            self.armor += 50.0
        elif power_up_type == PowerUpType.HEALTH:
            self.health = min(self.max_health, self.health + 30)
        elif power_up_type == PowerUpType.AMMO:
            if self.weapon:
                self.weapon.ammo = self.weapon.max_ammo
        elif power_up_type == PowerUpType.REGEN:
            self.health += 5.0  # Regen happens over time

    def update_power_ups(self, dt: float):
        """Update active power-ups and their durations"""
        for power_up_type in list(self.power_ups.keys()):
            if self.power_ups[power_up_type] > 0:
                self.power_ups[power_up_type] -= dt
                if self.power_ups[power_up_type] <= 0:
                    # Remove power-up effect
                    if power_up_type == PowerUpType.SPEED:
                        self.speed /= 1.5
                    elif power_up_type == PowerUpType.SHIELD:
                        self.armor = max(0, self.armor - 50.0)
                    # Remove the power-up
                    del self.power_ups[power_up_type]

    def take_damage(self, damage: float, source_robot: Optional['Robot'] = None):
        """Apply damage to robot, considering armor"""
        actual_damage = max(0, damage - (self.armor * 0.5))
        self.health -= actual_damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            if source_robot and source_robot.team != self.team:
                source_robot.stats["kills"] += 1
            self.stats["deaths"] += 1
            # Create death particles
            self.particles.extend([
                Particle(self.position.copy(), "explosion", (255, 100, 0), 3, 0.5)
                for _ in range(8)
            ])

    def heal(self, amount: float):
        """Heal robot by specified amount"""
        self.health = min(self.max_health, self.health + amount)

    def update(self, dt: float, game_state: 'GameState'):
        """Update robot state"""
        if not self.is_alive:
            return

        # Update cooldowns
        for cooldown in self.cooldowns:
            self.cooldowns[cooldown] = max(0, self.cooldowns[cooldown] - dt)

        # Update weapon cooldown
        if self.weapon:
            self.weapon_cooldown = max(0, self.weapon_cooldown - dt)

        # Update power-ups
        self.update_power_ups(dt)

        # Update position memory
        self.memory["recent_positions"].append(self.position.copy())

        # Update animations
        self.animation_timer += dt
        if self.animation_timer > 0.1:
            self.animation_frame = (self.animation_frame + 1) % 4
            self.animation_timer = 0.0

        # Update particles
        for particle in self.particles[:]:
            particle.update(dt)
            if particle.lifetime <= 0:
                self.particles.remove(particle)

        # Update strategy based on learning
        self._update_strategy(game_state)

    def _update_strategy(self, game_state: 'GameState'):
        """Adapt strategy based on performance and game context"""
        if len(self.memory["battle_outcomes"]) < 3:
            return

        # Calculate success rate for current strategy
        recent_outcomes = self.memory["battle_outcomes"][-5:]
        success_rate = sum(1 for outcome in recent_outcomes if outcome["success"]) / len(recent_outcomes)

        # If success rate is low, try a new strategy
        if success_rate < 0.3 and len(self.memory["battle_outcomes"]) > 5:
            strategies = ["defensive", "support", "aggressive", "stealth"]
            current_index = strategies.index(self.strategy)
            # Try a different strategy
            new_index = (current_index + 1) % len(strategies)
            self.strategy = strategies[new_index]
            self.memory["strategy_change"] = time.time()

        # Learn from team success
        team_success = game_state.get_team_success_rate(self.team)
        if team_success > 0.7 and self.role != "support":
            # Encourage team roles if team is doing well
            if random.random() < 0.3:
                self.role = random.choice(["support", "defender"])

        # Adapt based on experience
        if self.experience > 100:
            self.experience -= 1
            if random.random() < 0.1:
                # Improve decision making
                self.vision_range += 5
                self.speed = min(self.speed * 1.02, 250.0)

    def get_action(self, game_state: 'GameState') -> Dict[str, Any]:
        """Generate AI action based on current state and strategy"""
        if not self.is_alive:
            return {"action": "idle"}

        # Get teammates and enemies
        teammates = [r for r in game_state.robots if r.team == self.team and r.is_alive]
        enemies = [r for r in game_state.robots if r.team != self.team and r.is_alive]

        # Find nearest objectives
        nearest_objective = self._find_nearest_objective(game_state)

        # Get current position
        pos = self.position

        # Determine target based on role and strategy
        target = None
        if self.role == "flag_catcher" and nearest_objective and nearest_objective.obj_type == ObjectiveType.FLAG_CAPTURE:
            target = nearest_objective.position
        elif self.role == "payload_guard" and nearest_objective and nearest_objective.obj_type == ObjectiveType.PAYLOAD_ESCORT:
            target = nearest_objective.position
        elif self.role == "defender":
            # Defend base or objective
            base = game_state.get_team_base(self.team)
            if base:
                target = base.position
        elif self.role == "support":
            # Support teammate with lowest health
            if teammates:
                lowest_health = min(teammates, key=lambda t: t.health)
                if lowest_health.health < lowest_health.max_health * 0.5:
                    target = lowest_health.position
        else:  # attacker or default
            # Find closest enemy
            if enemies:
                target = min(enemies, key=lambda e: pos.distance_to(e.position)).position

        # Look for power-ups
        if target is None:
            power_ups = [pu for pu in game_state.power_ups if pu.active]
            if power_ups:
                nearest_powerup = min(power_ups, key=lambda pu: pos.distance_to(pu.position))
