class Hazard:
    """Represents an environmental hazard"""
    position: Vector2D
    hazard_type: HazardType
    radius: float = 100.0
    damage_per_second: float = 5.0
    duration: float = 0.0
    active: bool = True
    color: Tuple[int, int, int] = (255, 100, 0)
    spawn_time: float = 0.0

    def __post_init__(self):
        self.spawn_time = time.time()
        self.color = self._get_color()

    def _get_color(self) -> Tuple[int, int, int]:
        """Get color based on hazard type"""
        colors = {
            HazardType.LAVA: (255, 100, 0),
            HazardType.ELECTRIC: (100, 100, 255),
            HazardType.TOXIC: (100, 255, 100),
            HazardType.GRAVITY: (128, 0, 128)
        }
        return colors.get(self.hazard_type, (255, 100, 0))

    def apply_effect(self, robot: Robot) -> float:
        """Apply hazard effect to robot"""
        if not robot.is_alive:
            return 0.0

        distance = robot.position.distance_to(self.position)
        if distance > self.radius:
            return 0.0

        # Calculate damage based on distance
        damage = self.damage_per_second * (1 - distance / self.radius)

        # Apply different effects based on hazard type
        if self.hazard_type == HazardType.LAVA:
            robot.take_damage(damage * 1.5)
            robot.velocity *= 0.7  # Slow down
        elif self.hazard_type == HazardType.ELECTRIC:
            robot.take_damage(damage)
            robot.speed *= 0.5  # Reduce speed
        elif self.hazard_type == HazardType.TOXIC:
            robot.take_damage(damage)
            robot.max_health = max(10, robot.max_health * 0.95)  # Reduce max health
        elif self.hazard_type == HazardType.GRAVITY:
            robot.take_damage(damage * 0.5)
            robot.velocity *= 0.3  # Slow down significantly

        return damage

