        """Get color based on objective type and team"""
        if self.captured:
            if self.team == TEAM_BLUE:
                return (0, 100, 255)
            elif self.team == TEAM_RED:
                return (255, 100, 0)
            else:
                return (200, 200, 200)

        if self.obj_type == ObjectiveType.FLAG_CAPTURE:
            return (255, 215, 0)
        elif self.obj_type == ObjectiveType.PAYLOAD_ESCORT:
            return (128, 128, 128)
        elif self.obj_type == ObjectiveType.BASE_DEFENSE:
            if self.team == TEAM_BLUE:
                return (0, 100, 255)
            elif self.team == TEAM_RED:
                return (255, 100, 0)
            else:
                return (255, 255, 255)
        elif self.obj_type == ObjectiveType.CONTROL_POINT:
            return (255, 100, 255)
        else:
            return (255, 255, 255)

    def update(self, dt: float, robots: List[Robot]) -> bool:
        """Update objective state"""
        if self.captured:
            return True

        # Determine which team is near the objective
        nearby_robots = []
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius:
                if robot.team != TEAM_NEUTRAL:
                    nearby_robots.append(robot)

        # Check for capture
        team_counts = {TEAM_BLUE: 0, TEAM_RED: 0}
        for robot in nearby_robots:
            team_counts[robot.team] += 1

        # Determine dominant team
        dominant_team = None
        if team_counts[TEAM_BLUE] > team_counts[TEAM_RED] and team_counts[TEAM_BLUE] > 0:
            dominant_team = TEAM_BLUE
        elif team_counts[TEAM_RED] > team_counts[TEAM_BLUE] and team_counts[TEAM_RED] > 0:
            dominant_team = TEAM_RED

        # Update capture progress
        if dominant_team and dominant_team != self.capture_team:
            self.capture_team = dominant_team
            self.capture_progress = 0.0

        if dominant_team:
            self.capture_progress += dt / self.capture_time
            if self.capture_progress >= 1.0:
                self.captured = True
                self.team = dominant_team
                self.color = self._get_color()
                return True

        return False

    def get_status(self) -> Dict[str, Any]:
        """Get objective status for display"""
        return {
            "type": self.obj_type.value,
            "position": self.position.as_tuple(),
            "team": self.team,
            "captured": self.captured,
            "capture_progress": self.capture_progress,
            "capture_team": self.capture_team,
            "radius": self.radius
        }

