        elif power_up_type == PowerUpType.REGEN:
            self.health += 5.0  # Regen happens over time

    def update_power_ups(self, dt: float):
        """Update active power-ups and their durations"""
        for power_up_type in list(self.power_ups.keys()):
            if self.power_ups[power_up_type] > 0:
                self.power_ups[power_up_type] -= dt
                if self.power_ups[power_up_type] <= 0:
                    # Remove power-up effect
                    if power_up_type == PowerUpType.SPEED:
                        self.speed /= 1.5
                    elif power_up_type == PowerUpType.SHIELD:
                        self.armor = max(0, self.armor - 50.0)
                    # Remove the power-up
                    del self.power_ups[power_up_type]

    def take_damage(self, damage: float, source_robot: Optional['Robot'] = None):
        """Apply damage to robot, considering armor"""
        actual_damage = max(0, damage - (self.armor * 0.5))
        self.health -= actual_damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            if source_robot and source_robot.team != self.team:
                source_robot.stats["kills"] += 1
            self.stats["deaths"] += 1
            # Create death particles
            self.particles.extend([
                Particle(self.position.copy(), "explosion", (255, 100, 0), 3, 0.5)
                for _ in range(8)
            ])

    def heal(self, amount: float):
        """Heal robot by specified amount"""
        self.health = min(self.max_health, self.health + amount)

    def update(self, dt: float, game_state: 'GameState'):
        """Update robot state"""
        if not self.is_alive:
            return

        # Update cooldowns
        for cooldown in self.cooldowns:
            self.cooldowns[cooldown] = max(0, self.cooldowns[cooldown] - dt)

        # Update weapon cooldown
        if self.weapon:
            self.weapon_cooldown = max(0, self.weapon_cooldown - dt)

        # Update power-ups
        self.update_power_ups(dt)

        # Update position memory
        self.memory["recent_positions"].append(self.position.copy())

        # Update animations
        self.animation_timer += dt
        if self.animation_timer > 0.1:
            self.animation_frame = (self.animation_frame + 1) % 4
            self.animation_timer = 0.0

        # Update particles
        for particle in self.particles[:]:
            particle.update(dt)
            if particle.lifetime <= 0:
                self.particles.remove(particle)

        # Update strategy based on learning
        self._update_strategy(game_state)

    def _update_strategy(self, game_state: 'GameState'):
        """Adapt strategy based on performance and game context"""
        if len(self.memory["battle_outcomes"]) < 3:
            return

        # Calculate success rate for current strategy
        recent_outcomes = self.memory["battle_outcomes"][-5:]
        success_rate = sum(1 for outcome in recent_outcomes if outcome["success"]) / len(recent_outcomes)

        # If success rate is low, try a new strategy
        if success_rate < 0.3 and len(self.memory["battle_outcomes"]) > 5:
            strategies = ["defensive", "support", "aggressive", "stealth"]
            current_index = strategies.index(self.strategy)
            # Try a different strategy
            new_index = (current_index + 1) % len(strategies)
            self.strategy = strategies[new_index]
            self.memory["strategy_change"] = time.time()

        # Learn from team success
        team_success = game_state.get_team_success_rate(self.team)
        if team_success > 0.7 and self.role != "support":
            # Encourage team roles if team is doing well
            if random.random() < 0.3:
                self.role = random.choice(["support", "defender"])

        # Adapt based on experience
        if self.experience > 100:
            self.experience -= 1
            if random.random() < 0.1:
                # Improve decision making
                self.vision_range += 5
                self.speed = min(self.speed * 1.02, 250.0)

    def get_action(self, game_state: 'GameState') -> Dict[str, Any]:
        """Generate AI action based on current state and strategy"""
        if not self.is_alive:
            return {"action": "idle"}

        # Get teammates and enemies
        teammates = [r for r in game_state.robots if r.team == self.team and r.is_alive]
        enemies = [r for r in game_state.robots if r.team != self.team and r.is_alive]

        # Find nearest objectives
        nearest_objective = self._find_nearest_objective(game_state)

        # Get current position
        pos = self.position

        # Determine target based on role and strategy
        target = None
        if self.role == "flag_catcher" and nearest_objective and nearest_objective.obj_type == ObjectiveType.FLAG_CAPTURE:
            target = nearest_objective.position
        elif self.role == "payload_guard" and nearest_objective and nearest_objective.obj_type == ObjectiveType.PAYLOAD_ESCORT:
            target = nearest_objective.position
        elif self.role == "defender":
            # Defend base or objective
            base = game_state.get_team_base(self.team)
            if base:
                target = base.position
        elif self.role == "support":
            # Support teammate with lowest health
            if teammates:
                lowest_health = min(teammates, key=lambda t: t.health)
                if lowest_health.health < lowest_health.max_health * 0.5:
                    target = lowest_health.position
        else:  # attacker or default
            # Find closest enemy
            if enemies:
                target = min(enemies, key=lambda e: pos.distance_to(e.position)).position

        # Look for power-ups
        if target is None:
            power_ups = [pu for pu in game_state.power_ups if pu.active]
            if power_ups:
                nearest_powerup = min(power_ups, key=lambda pu: pos.distance_to(pu.position))
                if pos.distance_to(nearest_powerup.position) < self.vision_range:
                    target = nearest_powerup.position

        # Determine action based on target and surroundings
        if target:
            direction = (target - pos).normalize()
            distance = pos.distance_to(target)

            # Check if we can attack
            enemy_in_range = None
            if enemies:
                for enemy in enemies:
                    if pos.distance_to(enemy.position) < (self.weapon.attack_range if self.weapon else 200):
                        enemy_in_range = enemy
                        break

            # AI decision logic
            if enemy_in_range and self.weapon_cooldown <= 0 and self.weapon:
                # Attack if weapon is ready
                return {
                    "action": "attack", 
                    "target": enemy_in_range.id, 
                    "weapon": self.weapon.name,
                    "direction": direction.as_tuple()
                }
            elif distance < 50 and self.weapon and self.weapon.type == WeaponType.MELEE:
                # Melee attack if close enough
                return {
                    "action": "attack", 
                    "target": "close", 
                    "weapon": self.weapon.name,
                    "direction": direction.as_tuple()
                }
            elif distance > 150:
                # Move toward target
                return {
                    "action": "move", 
                    "target": target.as_tuple(), 
                    "direction": direction.as_tuple()
                }
            elif distance < 100:
                # Strafe or circle around target
                perpendicular = Vector2D(-direction.y, direction.x)
                if random.random() < 0.5:
                    move_dir = (direction + perpendicular * 0.5).normalize()
                else:
                    move_dir = (direction - perpendicular * 0.5).normalize()
                return {
                    "action": "move", 
                    "target": (pos + move_dir * 50).as_tuple(), 
                    "direction": move_dir.as_tuple()
                }
            else:
                # Move toward target
                return {
                    "action": "move", 
                    "target": target.as_tuple(), 
                    "direction": direction.as_tuple()
                }
        else:
            # Patrol or explore
            if random.random() < 0.3:
                # Random movement
                angle = random.uniform(0, math.pi * 2)
                move_dir = Vector2D(math.cos(angle), math.sin(angle))
                return {
                    "action": "move", 
                    "target": (pos + move_dir * 100).as_tuple(), 
                    "direction": move_dir.as_tuple()
                }
            else:
                # Idle or reposition
                return {"action": "idle"}

    def _find_nearest_objective(self, game_state: 'GameState') -> Optional['Objective']:
        """Find the nearest objective to this robot"""
        if not game_state.objectives:
            return None

        nearest = None
        min_distance = float('inf')
        pos = self.position

        for obj in game_state.objectives:
            distance = pos.distance_to(obj.position)
            if distance < min_distance:
                min_distance = distance
                nearest = obj

        return nearest if min_distance < self.vision_range else None

    def get_status(self) -> Dict[str, Any]:
        """Get robot status for display and logging"""
        return {
            "id": self.id,
            "team": self.team,
            "position": self.position.as_tuple(),
            "health": self.health,
            "max_health": self.max_health,
            "speed": self.speed,
            "armor": self.armor,
            "role": self.role,
            "strategy": self.strategy,
            "experience": self.experience,
            "kills": self.stats["kills"],
            "deaths": self.stats["deaths"],
            "assists": self.stats["assists"],
            "objectives": self.stats["objectives"],
            "is_alive": self.is_alive,
            "weapon": self.weapon.name if self.weapon else "none",
            "power_ups": [p.name for p in self.power_ups.keys() if self.power_ups[p] > 0]
        }

@dataclass
class Weapon:
    """Represents a weapon a robot can use"""
    name: str
    type: WeaponType
    damage: float
    range: float
    rate_of_fire: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float
    splash_radius: float = 0.0
    impact_effect: str = "none"

    def __post_init__(self):
        self.cooldown = 0.0
        self.is_reloading = False
        self.last_fired = 0.0

    def can_fire(self, current_time: float) -> bool:
        """Check if weapon can be fired"""
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self, current_time: float) -> bool:
        """Fire the weapon if possible"""
        if not self.can_fire(current_time):
            return False

        self.ammo -= 1
        self.last_fired = current_time
        self.cooldown = self.rate_of_fire
        self.is_reloading = False

        # Apply recoil
        return True

    def reload(self, current_time: float) -> bool:
        """Start reloading if ammo is low"""
        if self.ammo >= self.max_ammo:
            return False

        if not self.is_reloading:
            self.is_reloading = True
            return True

        return False

    def update(self, dt: float):
        """Update weapon state"""
        self.cooldown = max(0, self.cooldown - dt)

        # Automatic reload if not firing
        if self.is_reloading and self.ammo < self.max_ammo:
            reload_progress = self.reload_time / 3.0  # Assume 3 steps
            if random.random() < dt / reload_progress:
                self.ammo = min(self.max_ammo, self.ammo + 1)
                if self.ammo >= self.max_ammo:
                    self.is_reloading = False

@dataclass
class PowerUp:
    """Represents a power-up item in the arena"""
    position: Vector2D
    power_up_type: PowerUpType
    duration: float = 10.0
    spawn_time: float = 0.0
    active: bool = True
    value: float = 0.0
    color: Tuple[int, int, int] = (255, 255, 0)

    def __post_init__(self):
        self.spawn_time = time.time()
        self.color = self._get_color()
        self.value = self._get_value()

    def _get_color(self) -> Tuple[int, int, int]:
        """Get color based on power-up type"""
        colors = {
            PowerUpType.HEALTH: (0, 255, 0),
            PowerUpType.AMMO: (255, 255, 0),
            PowerUpType.SPEED: (0, 255, 255),
            PowerUpType.SHIELD: (0, 100, 255),
            PowerUpType.TELEPORT: (128, 0, 128),
            PowerUpType.STUN: (255, 0, 255),
            PowerUpType.REGEN: (128, 255, 128)
        }
        return colors.get(self.power_up_type, (255, 255, 0))

    def _get_value(self) -> float:
        """Get value based on power-up type"""
        values = {
            PowerUpType.HEALTH: 25.0,
            PowerUpType.AMMO: 15,
            PowerUpType.SPEED: 0.5,
            PowerUpType.SHIELD: 30.0,
            PowerUpType.TELEPORT: 1.0,
            PowerUpType.STUN: 3.0,
            PowerUpType.REGEN: 2.0
        }
        return values.get(self.power_up_type, 10.0)

    def get_effect(self) -> Dict[str, Any]:
        """Get effect description of the power-up"""
        effects = {
            PowerUpType.HEALTH: f"Heals {self.value} HP",
            PowerUpType.AMMO: f"Refills {self.value} ammo",
            PowerUpType.SPEED: f"Increases speed by {self.value * 100:.0f}%",
            PowerUpType.SHIELD: f"Adds {self.value} armor",
            PowerUpType.TELEPORT: "Teleports to random location",
            PowerUpType.STUN: f"Stuns enemies for {self.duration}s",
            PowerUpType.REGEN: f"Regenerates {self.value} HP/s"
        }
        return effects.get(self.power_up_type, "")

@dataclass
class Objective:
    """Represents a game objective (flag, payload, base, control point)"""
    obj_type: ObjectiveType
    position: Vector2D
    team: str = TEAM_NEUTRAL
    capture_progress: float = 0.0
    capture_team: Optional[str] = None
    captured: bool = False
    required_captures: int = 1
    capture_time: float = 10.0
    last_updated: float = 0.0
    radius: float = 60.0
    color: Tuple[int, int, int] = (255, 255, 255)
    name: str = ""

    def __post_init__(self):
        self.color = self._get_color()
        if not self.name:
            self.name = f"{self.obj_type.value}_{self.position.as_tuple()}"

    def _get_color(self) -> Tuple[int, int, int]:
        """Get color based on objective type and team"""
        if self.captured:
            if self.team == TEAM_BLUE:
                return (0, 100, 255)
            elif self.team == TEAM_RED:
                return (255, 100, 0)
            else:
                return (200, 200, 200)

        if self.obj_type == ObjectiveType.FLAG_CAPTURE:
            return (255, 215, 0)
        elif self.obj_type == ObjectiveType.PAYLOAD_ESCORT:
            return (128, 128, 128)
        elif self.obj_type == ObjectiveType.BASE_DEFENSE:
            if self.team == TEAM_BLUE:
                return (0, 100, 255)
            elif self.team == TEAM_RED:
                return (255, 100, 0)
            else:
                return (255, 255, 255)
        elif self.obj_type == ObjectiveType.CONTROL_POINT:
            return (255, 100, 255)
        else:
            return (255, 255, 255)

    def update(self, dt: float, robots: List[Robot]) -> bool:
        """Update objective state"""
        if self.captured:
            return True

        # Determine which team is near the objective
        nearby_robots = []
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius:
                if robot.team != TEAM_NEUTRAL:
                    nearby_robots.append(robot)

        # Check for capture
        team_counts = {TEAM_BLUE: 0, TEAM_RED: 0}
        for robot in nearby_robots:
            team_counts[robot.team] += 1

        # Determine dominant team
        dominant_team = None
        if team_counts[TEAM_BLUE] > team_counts[TEAM_RED] and team_counts[TEAM_BLUE] > 0:
            dominant_team = TEAM_BLUE
        elif team_counts[TEAM_RED] > team_counts[TEAM_BLUE] and team_counts[TEAM_RED] > 0:
            dominant_team = TEAM_RED

        # Update capture progress
        if dominant_team and dominant_team != self.capture_team:
            self.capture_team = dominant_team
            self.capture_progress = 0.0

        if dominant_team:
            self.capture_progress += dt / self.capture_time
            if self.capture_progress >= 1.0:
                self.captured = True
                self.team = dominant_team
                self.color = self._get_color()
                return True

        return False

    def get_status(self) -> Dict[str, Any]:
        """Get objective status for display"""
        return {
            "type": self.obj_type.value,
            "position": self.position.as_tuple(),
            "team": self.team,
            "captured": self.captured,
            "capture_progress": self.capture_progress,
            "capture_team": self.capture_team,
            "radius": self.radius
        }

@dataclass
class Hazard:
    """Represents an environmental hazard"""
    position: Vector2D
    hazard_type: HazardType
    radius: float = 100.0
    damage_per_second: float = 5.0
    duration: float = 0.0
    active: bool = True
    color: Tuple[int, int, int] = (255, 100, 0)
    spawn_time: float = 0.0

    def __post_init__(self):
        self.spawn_time = time.time()
        self.color = self._get_color()

    def _get_color(self) -> Tuple[int, int, int]:
        """Get color based on hazard type"""
        colors = {
            HazardType.LAVA: (255, 100, 0),
            HazardType.ELECTRIC: (100, 100, 255),
            HazardType.TOXIC: (100, 255, 100),
            HazardType.GRAVITY: (128, 0, 128)
        }
        return colors.get(self.hazard_type, (255, 100, 0))

    def apply_effect(self, robot: Robot) -> float:
        """Apply hazard effect to robot"""
        if not robot.is_alive:
            return 0.0

        distance = robot.position.distance_to(self.position)
        if distance > self.radius:
            return 0.0

        # Calculate damage based on distance
        damage = self.damage_per_second * (1 - distance / self.radius)

        # Apply different effects based on hazard type
        if self.hazard_type == HazardType.LAVA:
            robot.take_damage(damage * 1.5)
            robot.velocity *= 0.7  # Slow down
        elif self.hazard_type == HazardType.ELECTRIC:
            robot.take_damage(damage)
            robot.speed *= 0.5  # Reduce speed
        elif self.hazard_type == HazardType.TOXIC:
            robot.take_damage(damage)
            robot.max_health = max(10, robot.max_health * 0.95)  # Reduce max health
        elif self.hazard_type == HazardType.GRAVITY:
            robot.take_damage(damage * 0.5)
            robot.velocity *= 0.3  # Slow down significantly

        return damage

@dataclass
class Particle:
    """Represents a visual particle effect"""
    position: Vector2D
    particle_type: str
    color: Tuple[int, int, int]
    size: float
    lifetime: float
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    gravity: float = 0.0
    fade_rate: float = 0.0

    def update(self, dt: float):
        """Update particle position and state"""
        self.position = self.position + self.velocity * dt
        self.lifetime -= dt
        self.size = max(0, self.size - self.fade_rate * dt)

        # Apply gravity
        if self.gravity > 0:
            self.velocity.y += self.gravity * dt

@dataclass
class GameState:
    """Manages the overall game state"""
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    map_size: Tuple[int, int] = (SCREEN_WIDTH, SCREEN_HEIGHT)
    time_elapsed: float = 0.0
    current_objective: Optional[ObjectiveType] = None
    objectives_completed: Dict[ObjectiveType, int] = field(default_factory=lambda: defaultdict(int))
    team_scores: Dict[str, int] = field(default_factory=lambda: {TEAM_BLUE: 0, TEAM_RED: 0})
    round_duration: float = 300.0  # 5 minutes
    game_started: bool = False
    round_number: int = 1
    last_action_time: float = 0.0
    last_ai_update: float = 0.0
    ai_update_interval: float = 0.2
    difficulty: float = 0.5  # 0.0 = easy, 1.0 = hard
    team_wins: Dict[str, int] = field(default_factory=lambda: {TEAM_BLUE: 0, TEAM_RED: 0})
    audio_manager: Optional['AudioManager'] = None
    visual_effects: List[Particle] = field(default_factory=list)

    def __post_init__(self):
        self.team_scores = {TEAM_BLUE: 0, TEAM_RED: 0}
        self.objectives_completed = defaultdict(int)
        self.visual_effects = []

    def get_team_success_rate(self, team: str) -> float:
        """Calculate the success rate for a team based on historical performance"""
        if len(self.team_scores) < 2:
            return 0.5

        # Calculate based on recent wins and objective completions
        total_objectives = sum(self.objectives_completed.values())
        if total_objectives == 0:
            return 0.5

        team_objectives = sum(1 for obj in self.objectives if obj.team == team and obj.captured)
        team_wins = self.team_wins[team]

        # Weighted average
        if total_objectives > 0:
            win_rate = team_wins / (self.team_wins[TEAM_BLUE] + self.team_wins[TEAM_RED] + 1)
            objective_rate = team_objectives / total_objectives
            return (win_rate + objective_rate) / 2
        else:
            return 0.5

    def update_ai(self, dt: float):
        """Update all AI robots with new decisions"""
        if not self.game_started:
            return

        current_time = time.time()
        if current_time - self.last_ai_update < self.ai_update_interval:
            return

        self.last_ai_update = current_time

        # Update AI behavior based on difficulty
        difficulty_factor = self.difficulty

        for robot in self.robots:
            if not robot.is_alive:
                continue

            # Make AI more aggressive or defensive based on difficulty
            if difficulty_factor > 0.7:
                # Hard difficulty: more aggressive, faster reactions
                robot.vision_range = min(robot.vision_range + 20, 500)
                robot.speed = min(robot.speed * 1.05, 250.0)
            elif difficulty_factor < 0.3:
                # Easy difficulty: slower reactions, less aggressive
                robot.vision_range = max(robot.vision_range - 20, 150)
                robot.speed = max(robot.speed * 0.95, 80.0)

            # Determine action for robot
            action = robot.get_action(self)

            # Apply action
            if action["action"] == "attack":
                self._handle_attack(robot, action)
            elif action["action"] == "move":
                self._handle_move(robot, action)
            elif action["action"] == "idle":
                # Apply some random movement if idle for too long
                if random.random() < 0.3:
                    angle = random.uniform(0, math.pi * 2)
                    direction = Vector2D(math.cos(angle), math.sin(angle))
                    robot.velocity = direction * robot.speed * 0.5
                    robot.position += robot.velocity * dt
                continue

            # Update robot's last action time
            robot.last_action_time = current_time

    def _handle_attack(self, robot: Robot, action: Dict[str, Any]):
        """Handle attack action for robot"""
        if not robot.weapon or robot.weapon_cooldown > 0:
            return

        target_id = action.get("target")
        weapon = robot.weapon

        # Fire weapon
        if weapon.can_fire(time.time()):
            weapon.fire(time.time())
            robot.weapon_cooldown = weapon.rate_of_fire

            # Create muzzle flash
            direction = Vector2D(*action["direction"])
            muzzle_position = robot.position + direction * 20

            self.visual_effects.append(
                Particle(
                    muzzle_position,
                    "muzzle_flash",
                    (255, 255, 100),
                    10,
                    0.2,
                    direction * 20,
                    0,
                    30
                )
            )

            # Apply damage if targeting an enemy
            if target_id != "close":
                target_robot = next((r for r in self.robots if r.id == target_id), None)
                if target_robot and target_robot.is_alive:
                    # Calculate damage with range falloff
                    distance = robot.position.distance_to(target_robot.position)
                    damage_multiplier = max(0.2, 1 - (distance / weapon.range))
                    damage = weapon.damage * damage_multiplier

                    # Apply splash damage if applicable
                    if weapon.splash_radius > 0:
                        # Apply damage to nearby enemies
                        for enemy in self.robots:
                            if enemy.team != robot.team and enemy.is_alive:
                                dist = robot.position.distance_to(enemy.position)
                                if dist < weapon.splash_radius:
                                    splash_damage = damage * (1 - dist / weapon.splash_radius)
                                    enemy.take_damage(splash_damage, robot)
                                    # Create impact particles
                                    self.visual_effects.append(
                                        Particle(
                                            enemy.position,
                                            "impact",
                                            (255, 100, 100),
                                            5,
                                            0.3,
                                            Vector2D(random.uniform(-5, 5), random.uniform(-5, 5)),
                                            1.0,
                                            10
                                        )
                                    )

                    # Apply direct damage
                    target_robot.take_damage(damage, robot)

                    # Create impact effect
                    impact_position = target_robot.position
                    self.visual_effects.append(
