                    "direction": direction.as_tuple()
                }
        else:
            # Patrol or explore
            if random.random() < 0.3:
                # Random movement
                angle = random.uniform(0, math.pi * 2)
                move_dir = Vector2D(math.cos(angle), math.sin(angle))
                return {
                    "action": "move", 
                    "target": (pos + move_dir * 100).as_tuple(), 
                    "direction": move_dir.as_tuple()
                }
            else:
                # Idle or reposition
                return {"action": "idle"}

    def _find_nearest_objective(self, game_state: 'GameState') -> Optional['Objective']:
        """Find the nearest objective to this robot"""
        if not game_state.objectives:
            return None

        nearest = None
        min_distance = float('inf')
        pos = self.position

        for obj in game_state.objectives:
            distance = pos.distance_to(obj.position)
            if distance < min_distance:
                min_distance = distance
                nearest = obj

        return nearest if min_distance < self.vision_range else None

    def get_status(self) -> Dict[str, Any]:
        """Get robot status for display and logging"""
        return {
            "id": self.id,
            "team": self.team,
            "position": self.position.as_tuple(),
            "health": self.health,
            "max_health": self.max_health,
            "speed": self.speed,
            "armor": self.armor,
            "role": self.role,
            "strategy": self.strategy,
            "experience": self.experience,
            "kills": self.stats["kills"],
            "deaths": self.stats["deaths"],
            "assists": self.stats["assists"],
            "objectives": self.stats["objectives"],
            "is_alive": self.is_alive,
            "weapon": self.weapon.name if self.weapon else "none",
            "power_ups": [p.name for p in self.power_ups.keys() if self.power_ups[p] > 0]
        }

@dataclass
class Weapon:
    """Represents a weapon a robot can use"""
    name: str
    type: WeaponType
    damage: float
    range: float
    rate_of_fire: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float
    splash_radius: float = 0.0
    impact_effect: str = "none"

    def __post_init__(self):
        self.cooldown = 0.0
        self.is_reloading = False
        self.last_fired = 0.0

    def can_fire(self, current_time: float) -> bool:
        """Check if weapon can be fired"""
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self, current_time: float) -> bool:
        """Fire the weapon if possible"""
        if not self.can_fire(current_time):
            return False

        self.ammo -= 1
        self.last_fired = current_time
        self.cooldown = self.rate_of_fire
        self.is_reloading = False

        # Apply recoil
        return True

    def reload(self, current_time: float) -> bool:
        """Start reloading if ammo is low"""
        if self.ammo >= self.max_ammo:
            return False

        if not self.is_reloading:
            self.is_reloading = True
            return True

        return False

    def update(self, dt: float):
        """Update weapon state"""
        self.cooldown = max(0, self.cooldown - dt)

        # Automatic reload if not firing
        if self.is_reloading and self.ammo < self.max_ammo:
            reload_progress = self.reload_time / 3.0  # Assume 3 steps
            if random.random() < dt / reload_progress:
                self.ammo = min(self.max_ammo, self.ammo + 1)
                if self.ammo >= self.max_ammo:
                    self.is_reloading = False

