@dataclass
class Objective:
    """Represents a game objective (flag, payload, base, control point)"""
    obj_type: ObjectiveType
    position: Vector2D
    team: str = TEAM_NEUTRAL
    capture_progress: float = 0.0
    capture_team: Optional[str] = None
    captured: bool = False
    required_captures: int = 1
    capture_time: float = 10.0
    last_updated: float = 0.0
    radius: float = 60.0
    color: Tuple[int, int, int] = (255, 255, 255)
    name: str = ""

    def __post_init__(self):
        self.color = self._get_color()
        if not self.name:
            self.name = f"{self.obj_type.value}_{self.position.as_tuple()}"

    def _get_color(self) -> Tuple[int, int, int]:
        """Get color based on objective type and team"""
        if self.captured:
            if self.team == TEAM_BLUE:
                return (0, 100, 255)
            elif self.team == TEAM_RED:
                return (255, 100, 0)
            else:
                return (200, 200, 200)

        if self.obj_type == ObjectiveType.FLAG_CAPTURE:
            return (255, 215, 0)
        elif self.obj_type == ObjectiveType.PAYLOAD_ESCORT:
            return (128, 128, 128)
        elif self.obj_type == ObjectiveType.BASE_DEFENSE:
            if self.team == TEAM_BLUE:
                return (0, 100, 255)
            elif self.team == TEAM_RED:
                return (255, 100, 0)
            else:
                return (255, 255, 255)
        elif self.obj_type == ObjectiveType.CONTROL_POINT:
            return (255, 100, 255)
        else:
            return (255, 255, 255)

    def update(self, dt: float, robots: List[Robot]) -> bool:
        """Update objective state"""
        if self.captured:
            return True

        # Determine which team is near the objective
        nearby_robots = []
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) < self.radius:
                if robot.team != TEAM_NEUTRAL:
                    nearby_robots.append(robot)

        # Check for capture
        team_counts = {TEAM_BLUE: 0, TEAM_RED: 0}
        for robot in nearby_robots:
            team_counts[robot.team] += 1

        # Determine dominant team
        dominant_team = None
        if team_counts[TEAM_BLUE] > team_counts[TEAM_RED] and team_counts[TEAM_BLUE] > 0:
            dominant_team = TEAM_BLUE
        elif team_counts[TEAM_RED] > team_counts[TEAM_BLUE] and team_counts[TEAM_RED] > 0:
            dominant_team = TEAM_RED

        # Update capture progress
        if dominant_team and dominant_team != self.capture_team:
            self.capture_team = dominant_team
            self.capture_progress = 0.0

        if dominant_team:
            self.capture_progress += dt / self.capture_time
            if self.capture_progress >= 1.0:
                self.captured = True
                self.team = dominant_team
                self.color = self._get_color()
                return True

        return False

    def get_status(self) -> Dict[str, Any]:
        """Get objective status for display"""
        return {
            "type": self.obj_type.value,
            "position": self.position.as_tuple(),
            "team": self.team,
            "captured": self.captured,
            "capture_progress": self.capture_progress,
            "capture_team": self.capture_team,
            "radius": self.radius
        }

@dataclass
class Hazard:
    """Represents an environmental hazard"""
    position: Vector2D
    hazard_type: HazardType
    radius: float = 100.0
    damage_per_second: float = 5.0
    duration: float = 0.0
    active: bool = True
    color: Tuple[int, int, int] = (255, 100, 0)
    spawn_time: float = 0.0

    def __post_init__(self):
        self.spawn_time = time.time()
        self.color = self._get_color()

    def _get_color(self) -> Tuple[int, int, int]:
        """Get color based on hazard type"""
        colors = {
            HazardType.LAVA: (255, 100, 0),
            HazardType.ELECTRIC: (100, 100, 255),
            HazardType.TOXIC: (100, 255, 100),
            HazardType.GRAVITY: (128, 0, 128)
        }
        return colors.get(self.hazard_type, (255, 100, 0))

    def apply_effect(self, robot: Robot) -> float:
        """Apply hazard effect to robot"""
        if not robot.is_alive:
            return 0.0

        distance = robot.position.distance_to(self.position)
        if distance > self.radius:
            return 0.0

        # Calculate damage based on distance
        damage = self.damage_per_second * (1 - distance / self.radius)

        # Apply different effects based on hazard type
        if self.hazard_type == HazardType.LAVA:
            robot.take_damage(damage * 1.5)
            robot.velocity *= 0.7  # Slow down
        elif self.hazard_type == HazardType.ELECTRIC:
            robot.take_damage(damage)
            robot.speed *= 0.5  # Reduce speed
        elif self.hazard_type == HazardType.TOXIC:
            robot.take_damage(damage)
            robot.max_health = max(10, robot.max_health * 0.95)  # Reduce max health
        elif self.hazard_type == HazardType.GRAVITY:
            robot.take_damage(damage * 0.5)
            robot.velocity *= 0.3  # Slow down significantly

        return damage

@dataclass
class Particle:
    """Represents a visual particle effect"""
    position: Vector2D
    particle_type: str
    color: Tuple[int, int, int]
    size: float
    lifetime: float
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    gravity: float = 0.0
    fade_rate: float = 0.0

    def update(self, dt: float):
        """Update particle position and state"""
        self.position = self.position + self.velocity * dt
        self.lifetime -= dt
        self.size = max(0, self.size - self.fade_rate * dt)

        # Apply gravity
        if self.gravity > 0:
            self.velocity.y += self.gravity * dt

