    team_wins: Dict[str, int] = field(default_factory=lambda: {TEAM_BLUE: 0, TEAM_RED: 0})
    audio_manager: Optional['AudioManager'] = None
    visual_effects: List[Particle] = field(default_factory=list)

    def __post_init__(self):
        self.team_scores = {TEAM_BLUE: 0, TEAM_RED: 0}
        self.objectives_completed = defaultdict(int)
        self.visual_effects = []

    def get_team_success_rate(self, team: str) -> float:
        """Calculate the success rate for a team based on historical performance"""
        if len(self.team_scores) < 2:
            return 0.5

        # Calculate based on recent wins and objective completions
        total_objectives = sum(self.objectives_completed.values())
        if total_objectives == 0:
            return 0.5

        team_objectives = sum(1 for obj in self.objectives if obj.team == team and obj.captured)
        team_wins = self.team_wins[team]

        # Weighted average
        if total_objectives > 0:
            win_rate = team_wins / (self.team_wins[TEAM_BLUE] + self.team_wins[TEAM_RED] + 1)
            objective_rate = team_objectives / total_objectives
            return (win_rate + objective_rate) / 2
        else:
            return 0.5

    def update_ai(self, dt: float):
        """Update all AI robots with new decisions"""
        if not self.game_started:
            return

        current_time = time.time()
        if current_time - self.last_ai_update < self.ai_update_interval:
            return

        self.last_ai_update = current_time

        # Update AI behavior based on difficulty
        difficulty_factor = self.difficulty

        for robot in self.robots:
            if not robot.is_alive:
                continue

            # Make AI more aggressive or defensive based on difficulty
            if difficulty_factor > 0.7:
                # Hard difficulty: more aggressive, faster reactions
                robot.vision_range = min(robot.vision_range + 20, 500)
                robot.speed = min(robot.speed * 1.05, 250.0)
            elif difficulty_factor < 0.3:
                # Easy difficulty: slower reactions, less aggressive
                robot.vision_range = max(robot.vision_range - 20, 150)
                robot.speed = max(robot.speed * 0.95, 80.0)

            # Determine action for robot
            action = robot.get_action(self)

            # Apply action
            if action["action"] == "attack":
                self._handle_attack(robot, action)
            elif action["action"] == "move":
                self._handle_move(robot, action)
            elif action["action"] == "idle":
                # Apply some random movement if idle for too long
                if random.random() < 0.3:
                    angle = random.uniform(0, math.pi * 2)
                    direction = Vector2D(math.cos(angle), math.sin(angle))
                    robot.velocity = direction * robot.speed * 0.5
                    robot.position += robot.velocity * dt
                continue

            # Update robot's last action time
            robot.last_action_time = current_time

    def _handle_attack(self, robot: Robot, action: Dict[str, Any]):
        """Handle attack action for robot"""
        if not robot.weapon or robot.weapon_cooldown > 0:
