    shield: float = 0.0
    max_shield: float = 50.0
    speed: float = 1.0
    weapon: WeaponType = WeaponType.PISTOL
    ammo: int = 30
    max_ammo: int = 30
    cooldown: float = 0.0  # Weapon cooldown timer
    vision_range: float = 15.0
    is_alive: bool = True
    role: str = "default"  # Dynamic role: attacker, defender, support, etc.
    strategy: Dict[str, Any] = field(default_factory=dict)  # AI strategy parameters
    experience: float = 0.0  # Learning metric
    last_action_time: float = 0.0
    objectives: List[ObjectiveType] = field(default_factory=list)
    history: deque = field(default_factory=lambda: deque(maxlen=100))  # Battle history for learning

    def take_damage(self, damage: float, source: str = "unknown") -> float:
        """Apply damage to robot, considering shield first."""
        if not self.is_alive:
            return 0.0

        # Absorb shield first
        shield_absorbed = min(self.shield, damage)
        self.shield -= shield_absorbed
        remaining_damage = damage - shield_absorbed

        # Apply remaining damage to health
        self.health = max(0, self.health - remaining_damage)

        if self.health <= 0:
            self.is_alive = False
            logger.info(f"Robot {self.id} ({self.team.value}) has been eliminated by {source}")

        return remaining_damage

    def heal(self, amount: float) -> float:
        """Heal robot, respecting max health and shield limits."""
        if not self.is_alive:
            return 0.0

        # Heal health first
        health_gained = min(self.max_health - self.health, amount)
        self.health += health_gained

        # Then heal shield
        remaining_heal = amount - health_gained
        shield_gained = min(self.max_shield - self.shield, remaining_heal)
        self.shield += shield_gained

        return health_gained + shield_gained

    def recharge_ammo(self, amount: int = 30) -> int:
        """Recharge weapon ammo."""
        if not self.is_alive:
            return 0
        old_ammo = self.ammo
        self.ammo = min(self.max_ammo, self.ammo + amount)
        return self.ammo - old_ammo

    def add_experience(self, exp: float) -> None:
        """Add experience and potentially level up."""
        self.experience += exp
        # Simple leveling: every 100 exp increases stats slightly
        if self.experience >= 100:
            self.experience -= 100
            self.max_health += 5
            self.max_shield += 2
            self.speed += 0.05
            self.vision_range += 1.0
            self.max_ammo += 5
            logger.info(f"Robot {self.id} leveled up! Stats increased.")

    def update_strategy(self, context: Dict[str, Any]) -> None:
        """Update AI strategy based on environment and team performance."""
        # Simple adaptive strategy based on experience and team success
        if self.experience > 200:
            self.strategy['aggression'] = min(1.0, self.strategy.get('aggression', 0.5) + 0.1)
            self.strategy['teamwork'] = min(1.0, self.strategy.get('teamwork', 0.5) + 0.1)
        else:
            self.strategy['aggression'] = max(0.1, self.strategy.get('aggression', 0.5) - 0.05)

        # Adjust role based on team needs
        if context.get('team_health_ratio', 0.8) < 0.5:
            if self.robot_type == RobotType.HEALER:
                self.role = "priority_healer"
            elif self.robot_type == RobotType.TANK:
                self.role = "priority_defender"

        # Store in history for learning
        self.history.append({
            'timestamp': time.time(),
            'health': self.health,
            'shield': self.shield,
            'team_position': context.get('team_position', 'unknown'),
            'objective_progress': context.get('objective_progress', 0),
            'strategy': self.strategy.copy()
        })

    def get_action(self, game_state: 'GameState') -> Dict[str, Any]:
        """Determine the next action based on AI strategy and game state."""
        if not self.is_alive:
            return {"action": "idle", "target": None, "priority": 0}

        # Base actions
        actions = []

        # Check for nearby enemies
        nearby_enemies = [
            robot for robot in game_state.robots 
            if robot.team != self.team and robot.is_alive 
            and self.position.distance_to(robot.position) < self.vision_range
        ]

        # Check for objectives
        objectives = game_state.objectives
        nearby_objectives = [
            obj for obj in objectives 
            if self.position.distance_to(obj.position) < self.vision_range + 5
        ]

        # Check for power-ups
        power_ups = game_state.power_ups
        nearby_power_ups = [
            pu for pu in power_ups 
            if self.position.distance_to(pu.position) < self.vision_range
        ]

        # Check for hazards
        hazards = game_state.hazards
        nearby_hazards = [
            h for h in hazards 
            if self.position.distance_to(h.position) < self.vision_range
        ]

        # Strategy decision tree based on role and type
        if self.role == "priority_healer" and self.robot_type == RobotType.HEALER:
            # Find lowest health teammate
            teammates = [r for r in game_state.robots if r.team == self.team and r.is_alive]
            if teammates:
                lowest_health = min(teammates, key=lambda x: x.health)
                if lowest_health.health < 50:
                    return {
                        "action": "heal",
                        "target": lowest_health.id,
                        "priority": 10
                    }

        if self.role == "priority_defender" and self.robot_type == RobotType.TANK:
            # Defend objective or base
            for obj in nearby_objectives:
                if obj.type == ObjectiveType.DEFEND_BASE or obj.type == ObjectiveType.CONTROL_POINT:
                    return {
                        "action": "defend",
                        "target": obj.id,
                        "priority": 9
                    }

        # Attack if enemy nearby
        if nearby_enemies:
            closest_enemy = min(nearby_enemies, key=lambda x: self.position.distance_to(x.position))
            if self.weapon in [WeaponType.PISTOL, WeaponType.RIFLE, WeaponType.SHOTGUN, WeaponType.SNIPER_RIFLE, WeaponType.LASER, WeaponType.ROCKET_LAUNCHER]:
                if self.ammo > 0 and self.cooldown <= 0:
                    return {
                        "action": "attack",
                        "target": closest_enemy.id,
                        "priority": 8
                    }
            else:  # Melee
                if self.position.distance_to(closest_enemy.position) < 2.0:
                    return {
                        "action": "melee",
                        "target": closest_enemy.id,
                        "priority": 7
                    }

        # Go to power-up if beneficial
        if nearby_power_ups:
            closest_power_up = min(nearby_power_ups, key=lambda x: self.position.distance_to(x.position))
            if closest_power_up.type == PowerUpType.HEALTH_PACK and self.health < 80:
                return {
                    "action": "collect",
                    "target": closest_power_up.id,
                    "priority": 6
                }
            elif closest_power_up.type == PowerUpType.SPEED_BOOST:
                return {
                    "action": "collect",
                    "target": closest_power_up.id,
                    "priority": 5
                }

        # Move toward objective if no immediate threats
        if nearby_objectives:
            closest_obj = min(nearby_objectives, key=lambda x: self.position.distance_to(x.position))
            if closest_obj.type == ObjectiveType.CAPTURE_FLAG and self.team == closest_obj.team:
                return {
                    "action": "capture",
                    "target": closest_obj.id,
                    "priority": 4
                }
            elif closest_obj.type == ObjectiveType.ESCAPE_PAYLOAD:elif closest_obj.type == ObjectiveType.ESCORT_PAYLOAD:
                return {
                    "action": "escort",
                    "target": closest_obj.id,
                    "priority": 4
                }                return {
                    "action": "escort",
                    "target": closest_obj.id,
                    "priority": 4
                }
            elif closest_obj.type == ObjectiveType.CONTROL_POINT:
                return {
                    "action": "capture",
                    "target": closest_obj.id,
                    "priority": 4
                }

        # Avoid hazards
        if nearby_hazards:
            danger_hazard = min(nearby_hazards, key=lambda x: self.position.distance_to(x.position))
            # Move away from hazard
            away_vector = self.position - danger_hazard.position
            if away_vector.x != 0 or away_vector.y != 0:
                target_pos = self.position + away_vector.normalize() * 3.0
                return {
                    "action": "move",
                    "target": target_pos,
                    "priority": 3
                }

        # Default behavior: patrol or move toward base
        if self.team == Team.RED:
            base_pos = Vector2D(10, 10)
        else:
            base_pos = Vector2D(90, 90)

        if self.position.distance_to(base_pos) > 15:
            return {
                "action": "move",
                "target": base_pos,
                "priority": 2
            }

        # Idle if no action needed
        return {
            "action": "idle",
            "target": None,
            "priority": 0
        }

@dataclass
class Objective:
    id: str
    type: ObjectiveType
    position: Vector2D
    team: Team
    captured: bool = False
    capture_progress: float = 0.0
    capture_rate: float = 0.1  # per second
    radius: float = 5.0

    def update(self, robots_on_objective: List[Robot], dt: float) -> None:
        """Update capture progress based on robots on objective."""
        self.capture_progress = max(0, min(100, self.capture_progress))

        if self.captured:
            return

        # Determine which team is capturing
        capturing_team = None
        opposing_team = None
        team_count = 0
        opposing_count = 0

        for robot in robots_on_objective:
            if robot.team == self.team:
                team_count += 1
            elif robot.is_alive:
                opposing_count += 1

        # Capture logic: if team members are present, capture progresses
        if team_count > 0 and opposing_count == 0:
            self.capture_progress += self.capture_rate * team_count * dt
            if self.capture_progress >= 100:
                self.captured = True
                logger.info(f"Objective {self.id} captured by {self.team.value}!")
        elif opposing_count > 0 and team_count > 0:
            # Enemy contesting, progress slows or reverses
            self.capture_progress -= self.capture_rate * opposing_count * dt / 2
        elif opposing_count > 0:
            # Enemy trying to capture
            self.capture_progress -= self.capture_rate * opposing_count * dt
            if self.capture_progress <= 0:
                self.captured = True
                self.team = opposing_count > 0 and [r.team for r in robots_on_objective if r.team != self.team][0] or self.team
                logger.info(f"Objective {self.id} captured by {self.team.value}!")

        # Cap progress
        self.capture_progress = max(0, min(100, self.capture_progress))

@dataclass
class PowerUp:
    id: str
    type: PowerUpType
    position: Vector2D
    active: bool = True
    duration: float = 10.0  # seconds
    spawn_time: float = 0.0
    respawn_time: float = 30.0  # seconds until respawn

    def update(self, dt: float) -> None:
        """Update power-up state."""
        if not self.active:
            # Check if it's time to respawn
            if time.time() - self.spawn_time >= self.respawn_time:
                self.active = True
                logger.info(f"Power-up {self.id} has respawned.")

@dataclass
class Hazard:
    id: str
    type: HazardType
    position: Vector2D
    radius: float = 3.0
    damage: float = 5.0
    damage_rate: float = 0.5  # damage per second
    active: bool = True

    def apply_damage(self, robot: Robot, dt: float) -> float:
        """Apply damage to robot if within range."""
        if not self.active or not robot.is_alive:
            return 0.0

        distance = self.position.distance_to(robot.position)
        if distance <= self.radius:
            damage_dealt = self.damage * dt * self.damage_rate
            robot.take_damage(damage_dealt, f"hazard_{self.id}")
            return damage_dealt
        return 0.0

@dataclass
class GameState:
    """Holds the complete state of the arena."""
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    map_size: Tuple[float, float] = (100.0, 100.0)
    time_elapsed: float = 0.0
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    round_timer: float = 300.0  # 5 minutes per round
    game_phase: str = "preparation"  # preparation, active, overtime, ended
    last_update: float = 0.0
    dynamic_difficulty: float = 0.5  # 0.0 = easy, 1.0 = hard

    def add_robot(self, robot: Robot) -> None:
        self.robots.append(robot)

    def add_objective(self, obj: Objective) -> None:
        self.objectives.append(obj)

    def add_power_up(self, pu: PowerUp) -> None:
        self.power_ups.append(pu)

    def add_hazard(self, hazard: Hazard) -> None:
        self.hazards.append(hazard)

    def update(self, dt: float) -> None:
        """Update the game state."""
        self.time_elapsed += dt
        self.round_timer -= dt

        # Update objectives
        for obj in self.objectives:
            # Find robots within objective radius
            robots_on_obj = [
                robot for robot in self.robots 
                if robot.is_alive and robot.position.distance_to(obj.position) < obj.radius
            ]
            obj.update(robots_on_obj, dt)

            # Update scoring based on captured objectives
            if obj.captured:
                self.team_scores[obj.team] += 1

        # Update power-ups
        for pu in self.power_ups:
            pu.update(dt)

        # Update hazards
        for hazard in self.hazards:
            # Apply damage to robots in hazard
            for robot in self.robots:
                if robot.is_alive:
                    hazard.apply_damage(robot, dt)

        # Update robot cooldowns
        for robot in self.robots:
            if robot.is_alive:
                robot.cooldown = max(0, robot.cooldown - dt)

        # Update adaptive difficulty based on team performance
        self._update_difficulty()

        # Check game end conditions
        if self.round_timer <= 0 and self.game_phase == "active":
            self.game_phase = "ended"
            logger.info("Round ended!")

        # Update robot strategies based on game state
        for robot in self.robots:
            if robot.is_alive:
                context = {
                    'team_health_ratio': self._get_team_health_ratio(robot.team),
                    'team_position': self._get_team_position(robot.team),
                    'objective_progress': self._get_objective_progress(),
                    'dynamic_difficulty': self.dynamic_difficulty
                }
                robot.update_strategy(context)

        # Update last update time
        self.last_update = time.time()

    def _get_team_health_ratio(self, team: Team) -> float:
        """Calculate the health ratio of a team."""
        team_robots = [r for r in self.robots if r.team == team and r.is_alive]
        if not team_robots:
            return 0.0

        total_health = sum(r.health for r in team_robots)
        total_max_health = sum(r.max_health for r in team_robots)
        return total_health / total_max_health if total_max_health > 0 else 0.0

    def _get_team_position(self, team: Team) -> str:
        """Determine team's position relative to objectives."""
        team_robots = [r for r in self.robots if r.team == team and r.is_alive]
        if not team_robots:
            return "defeated"

        # Proximity to objectives of their team
        own_objectives = [o for o in self.objectives if o.team == team]
        if not own_objectives:
            return "neutral"

        total_distance = sum(
            min(r.position.distance_to(obj.position) for obj in own_objectives) 
            for r in team_robots
        ) / len(team_robots)

        if total_distance < 10:
            return "dominating"
        elif total_distance < 25:
            return "contesting"
        else:
            return "retreating"

    def _get_objective_progress(self) -> float:
        """Get average objective capture progress."""
        if not self.objectives:
            return 0.0
        return sum(obj.capture_progress for obj in self.objectives) / len(self.objectives)

    def _update_difficulty(self) -> None:
        """Adjust difficulty based on team performance."""
        red_team_health = self._get_team_health_ratio(Team.RED)
        blue_team_health = self._get_team_health_ratio(Team.BLUE)

        # If one team is consistently dominant, increase difficulty for them
        if red_team_health > 0.8 and blue_team_health < 0.3:
            self.dynamic_difficulty = min(1.0, self.dynamic_difficulty + 0.01)
        elif blue_team_health > 0.8 and red_team_health < 0.3:
            self.dynamic_difficulty = min(1.0, self.dynamic_difficulty + 0.01)
        elif red_team_health < 0.3 and blue_team_health < 0.3:
            # Both teams are struggling - make it easier
            self.dynamic_difficulty = max(0.1, self.dynamic_difficulty - 0.01)
        else:
            # Balanced game, keep difficulty steady
            self.dynamic_difficulty = max(0.2, min(0.8, self.dynamic_difficulty))

        # Apply difficulty to AI behavior
        for robot in self.robots:
            if not robot.is_alive:
                continue

            # Adjust AI behavior based on difficulty
            if self.dynamic_difficulty > 0.7:
                robot.strategy['aggression'] = min(1.0, robot.strategy.get('aggression', 0.5) + 0.1)
                robot.strategy['accuracy'] = min(1.0, robot.strategy.get('accuracy', 0.5) + 0.1)
                robot.vision_range = min(25.0, robot.vision_range + 1.0)
            elif self.dynamic_difficulty < 0.3:
                robot.strategy['aggression'] = max(0.1, robot.strategy.get('aggression', 0.5) - 0.1)
                robot.strategy['accuracy'] = max(0.1, robot.strategy.get('accuracy', 0.5) - 0.1)
                robot.vision_range = max(10.0, robot.vision_range - 1.0)

    def get_winner(self) -> Optional[Team]:
        """Determine winner based on team scores."""
        if self.team_scores[Team.RED] > self.team_scores[Team.BLUE]:
            return Team.RED
        elif self.team_scores[Team.BLUE] > self.team_scores[Team.RED]:
            return Team.BLUE
        else:
            return None  # Tie

