class CyberArena:
    """Main game engine for CyberArena."""

    def __init__(self):
        self.game_state = GameState()
        self.running = False
        self.last_tick_time = 0.0
        self.tick_rate = 1/60.0  # 60 FPS
        self.audio_queue = queue.Queue()
        self.visual_effects = []
        self.learning_data = []  # For machine learning feedback loop
        self.control_scheme = "default"  # "default", "keyboard", "controller"

        # Initialize the arena
        self._initialize_arena()

    def _initialize_arena(self) -> None:
        """Initialize the game environment with robots, objectives, power-ups, and hazards."""
        logger.info("Initializing CyberArena...")

        # Create robots
        team_sizes = 4  # 4 per team
        for i in range(team_sizes):
            # Red Team
            robot_type = random.choice([RobotType.SCORCH, RobotType.TANK, RobotType.HEALER, RobotType.SNIPER, RobotType.ENGINEER])
            robot = Robot(
                id=f"red_{i}",
                team=Team.RED,
                robot_type=robot_type,
                position=Vector2D(random.uniform(5, 25), random.uniform(5, 25)),
                weapon=self._get_default_weapon(robot_type),
                strategy={
                    'aggression': 0.5,
                    'teamwork': 0.5,
                    'accuracy': 0.7
                }
            )
            self.game_state.add_robot(robot)

            # Blue Team
            robot_type = random.choice([RobotType.SCORCH, RobotType.TANK, RobotType.HEALER, RobotType.SNIPER, RobotType.ENGINEER])
            robot = Robot(
                id=f"blue_{i}",
                team=Team.BLUE,
                robot_type=robot_type,
                position=Vector2D(random.uniform(75, 95), random.uniform(75, 95)),
                weapon=self._get_default_weapon(robot_type),
                strategy={
                    'aggression': 0.5,
                    'teamwork': 0.5,
                    'accuracy': 0.7
                }
            )
            self.game_state.add_robot(robot)

        # Create objectives
        objectives = [
            Objective("obj_1", ObjectiveType.CAPTURE_FLAG, Vector2D(50, 30), Team.RED),
            Objective("obj_2", ObjectiveType.CAPTURE_FLAG, Vector2D(50, 70), Team.BLUE),
            Objective("obj_3", ObjectiveType.CONTROL_POINT, Vector2D(30, 50), Team.RED),
            Objective("obj_4", ObjectiveType.CONTROL_POINT, Vector2D(70, 50), Team.BLUE)
        ]

        for obj in objectives:
            self.game_state.add_objective(obj)

        # Create power-ups
        power_ups = [
            PowerUp("pu_1", PowerUpType.HEALTH_PACK, Vector2D(20, 50)),
            PowerUp("pu_2", PowerUpType.SHIELD_BOOST, Vector2D(80, 50)),
            PowerUp("pu_3", PowerUpType.SPEED_BOOST, Vector2D(50, 15)),
            PowerUp("pu_4", PowerUpType.DAMAGE_BOOST, Vector2D(50, 85)),
            PowerUp("pu_5", PowerUpType.AMMO_RELOAD, Vector2D(40, 40)),
            PowerUp("pu_6", PowerUpType.INVISIBILITY, Vector2D(60, 60))
        ]

        for pu in power_ups:
            self.game_state.add_power_up(pu)

        # Create hazards
        hazards = [
            Hazard("haz_1", HazardType.LAVA, Vector2D(25, 25), radius=4.0, damage=10.0, damage_rate=0.8),
            Hazard("haz_2", HazardType.ELECTRIC_FIELD, Vector2D(75, 75), radius=3.5, damage=8.0, damage_rate=0.6),
            Hazard("haz_3", HazardType.MINEFIELD, Vector2D(50, 50), radius=6.0, damage=5.0, damage_rate=0.4)
        ]

        for hazard in hazards:
            self.game_state.add_hazard(hazard)

        # Set game phase to active
        self.game_state.game_phase = "active"
        logger.info(f"CyberArena initialized with {len(self.game_state.robots)} robots and {len(self.game_state.objectives)} objectives.")

    def _get_default_weapon(self, robot_type: RobotType) -> WeaponType:
        """Return default weapon for robot type."""
        weapon_map = {
            RobotType.SCORCH: WeaponType.SHOTGUN,
            RobotType.TANK: WeaponType.ROCKET_LAUNCHER,
            RobotType.HEALER: WeaponType.LASER,
            RobotType.SNIPER: WeaponType.SNIPER_RIFLE,
            RobotType.ENGINEER: WeaponType.RIFLE
        }
        return weapon_map.get(robot_type, WeaponType.PISTOL)

    def _apply_action(self, robot: Robot, action: Dict[str, Any]) -> None:
        """Apply a robot's chosen action to the game state."""
        if not robot.is_alive:
            return

        if action["action"] == "attack":
            target_robot = next((r for r in self.game_state.robots if r.id == action["target"]), None)
            if target_robot and target_robot.is_alive and robot.cooldown <= 0:
                # Calculate damage based on weapon and accuracy
                weapon_damage = {
                    WeaponType.PISTOL: 10,
                    WeaponType.RIFLE: 15,
                    WeaponType.SHOTGUN: 25,
                    WeaponType.SNIPER_RIFLE: 40,
                    WeaponType.LASER: 20,
                    WeaponType.ROCKET_LAUNCHER: 50
                }

                damage = weapon_damage.get(robot.weapon, 10)

                # Apply accuracy based on strategy
                accuracy = robot.strategy.get('accuracy', 0.7)
                if random.random() < accuracy:
                    # Add a small random factor for realism
                    damage = damage * random.uniform(0.8, 1.2)
                    target_robot.take_damage(damage, f"robot_{robot.id}")

                    # Give experience for successful hit
                    robot.add_experience(10.0)
                    target_robot.add_experience(2.0)  # Experience for being hit

                    # Audio feedback
                    self.audio_queue.put(f"weapon_fire_{robot.weapon.name.lower()}_hit")

                    # Visual effect
                    self.visual_effects.append({
                        'type': 'bullet_impact',
                        'position': target_robot.position,
                        'color': 'red',
                        'duration': 0.5
                    })
                else:
                    # Missed shot
                    self.audio_queue.put(f"weapon_fire_{robot.weapon.name.lower()}_miss")

                # Apply cooldown
                cooldown_map = {
                    WeaponType.PISTOL: 0.2,
                    WeaponType.RIFLE: 0.3,
                    WeaponType.SHOTGUN: 0.8,
                    WeaponType.SNIPER_RIFLE: 1.5,
                    WeaponType.LASER: 0.5,
                    WeaponType.ROCKET_LAUNCHER: 2.0
                }
                robot.cooldown = cooldown_map.get(robot.weapon, 0.5)
                robot.ammo -= 1
                if robot.ammo <= 0:
