@dataclass
class Vector2D:
    """2D position and velocity vector."""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def rotate(self, angle_radians):
        cos_a = math.cos(angle_radians)
        sin_a = math.sin(angle_radians)
        return Vector2D(
            self.x * cos_a - self.y * sin_a,
            self.x * sin_a + self.y * cos_a
        )

    def to_tuple(self):
        return (self.x, self.y)


@dataclass
class Weapon:
    """Represents a weapon with attributes and behavior."""
    name: str
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    cooldown: float = 0.0  # current cooldown
    ammo: int = 100
    max_ammo: int = 100
    spread: float = 0.0  # angular spread for ranged weapons
    knockback: float = 0.0
    projectile_speed: float = 10.0  # for ranged weapons
    area_effect_radius: float = 0.0  # for explosives

    def can_fire(self):
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self):
        if self.can_fire():
            self.ammo -= 1
            self.cooldown = self.fire_rate
            return True
        return False

    def update(self, delta_time: float):
        if self.cooldown > 0:
            self.cooldown -= delta_time
        if self.ammo < self.max_ammo:
            # Recharge ammo over time (slowly)
            self.ammo = min(self.max_ammo, self.ammo + delta_time * 0.5)


@dataclass
class Robot:
    """Represents an AI-controlled robot in the arena."""
    robot_id: str
    team: RobotTeam
    role: RobotRole
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D())
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    speed: float = 3.0
    rotation: float = 0.0  # radians
    weapon: Weapon = field(default_factory=lambda: Weapon(
        name="Plasma Rifle",
        weapon_type=WeaponType.RANGED,
        damage=25,
        range=300,
        fire_rate=0.5,
        ammo=80,
        max_ammo=80,
        spread=0.1,
        projectile_speed=15.0
    ))
    secondary_weapon: Optional[Weapon] = None
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)  # type -> duration
    vision_range: float = 200.0
    is_active: bool = True
    last_action_time: float = 0.0
    strategy_memory: List[Dict] = field(default_factory=list)  # history of decisions
    team_cooperation_score: float = 0.0  # how well the robot works with teammates
    last_known_enemies: List[str] = field(default_factory=list)  # IDs of known enemies

    def __post_init__(self):
        if not self.robot_id:
            self.robot_id = str(uuid.uuid4())

    def take_damage(self, damage: float, source: str = "unknown") -> bool:
        """Apply damage to robot, considering armor."""
        effective_damage = damage * (1 - min(self.armor / 100, 0.8))
        self.health -= effective_damage
        if self.health <= 0:
            self.health = 0
            self.is_active = False
            return True
        return False

    def heal(self, amount: float):
        """Heal the robot."""
        self.health = min(self.max_health, self.health + amount)

    def add_power_up(self, power_type: PowerUpType, duration: float):
        """Apply a power-up effect."""
        self.power_ups[power_type] = duration
        if power_type == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
        elif power_type == PowerUpType.SHIELD:
            self.armor = min(80, self.armor + 30)

    def update_power_ups(self, delta_time: float):
        """Update active power-ups and remove expired ones."""
        expired = []
        for power_type, duration in self.power_ups.items():
            self.power_ups[power_type] = duration - delta_time
            if self.power_ups[power_type] <= 0:
                expired.append(power_type)

        for power in expired:
            if power == PowerUpType.SPEED_BOOST:
                self.speed /= 1.5
            elif power == PowerUpType.SHIELD:
                self.armor = max(0, self.armor - 30)
            del self.power_ups[power]

    def update_weapon(self, delta_time: float):
        """Update weapon cooldowns and ammo regeneration."""
        self.weapon.update(delta_time)
        if self.secondary_weapon:
            self.secondary_weapon.update(delta_time)

    def move_towards(self, target: Vector2D, delta_time: float) -> bool:
        """Move robot towards target with pathfinding consideration."""
        if self.position.distance_to(target) < 2.0:  # Close enough
            return False

        direction = (target - self.position).normalize()
        move_distance = self.speed * delta_time
        self.position += direction * move_distance
        # Point towards target
        angle_to_target = math.atan2(target.y - self.position.y, target.x - self.position.x)
        self.rotation = angle_to_target
        return True

    def fire_at(self, target: Vector2D) -> Optional[Dict]:
        """Fire weapon at target position. Returns projectile data if fired."""
        if not self.weapon.can_fire():
            return None

        if self.weapon.weapon_type == WeaponType.RANGED:
            # Calculate direction vector
            direction = (target - self.position).normalize()

            # Add slight spread for realism
            if self.weapon.spread > 0:
                angle_offset = random.uniform(-self.weapon.spread, self.weapon.spread)
                direction = direction.rotate(angle_offset)

            projectile = {
                'position': self.position + direction * 10,  # spawn slightly ahead
                'velocity': direction * self.weapon.projectile_speed,
                'damage': self.weapon.damage,
                'team': self.team,
                'source': self.robot_id,
                'type': 'ranged'
            }

            self.weapon.fire()
            return projectile

        elif self.weapon.weapon_type == WeaponType.MELEE:
            # Check if in melee range
            distance = self.position.distance_to(target)
            if distance <= 30:  # melee range
                self.weapon.fire()
                return {'type': 'melee', 'damage': self.weapon.damage, 'source': self.robot_id}

        return None

    def get_sensed_enemies(self, robots: List['Robot']) -> List['Robot']:
        """Identify enemies within vision range."""
        enemies = []
        for robot in robots:
            if robot.team != self.team and robot.is_active:
                if self.position.distance_to(robot.position) <= self.vision_range:
                    enemies.append(robot)
        return enemies

    def add_strategy_memory(self, action: str, context: Dict, outcome: str):
        """Record a strategic decision and outcome for learning."""
        self.strategy_memory.append({
            'timestamp': time.time(),
            'action': action,
            'context': context,
            'outcome': outcome,
            'team_cooperation': self.team_cooperation_score
        })
        # Keep history limited
        if len(self.strategy_memory) > 50:
            self.strategy_memory.pop(0)

    def get_best_strategy(self, context: Dict) -> str:
        """Use memory to select best past strategy based on similar context."""
        if not self.strategy_memory:
            return "default"

        # Simple similarity matching based on context keys
        best_match = None
        best_score = -1

        for memory in self.strategy_memory:
            score = 0
            for key, value in context.items():
                if key in memory['context'] and memory['context'][key] == value:
                    score += 1

            if score > best_score and memory['outcome'] == 'success':
                best_score = score
                best_match = memory['action']

        return best_match if best_match else "default"

    def calculate_ai_decision(self, arena: 'CyberArena') -> str:
        """Core AI decision-making logic."""
        # Gather context
        enemies = self.get_sensed_enemies(arena.robots)
        objectives = arena.active_objectives
        teammates = [r for r in arena.robots if r.team == self.team and r.is_active]

        # Context dictionary for strategy selection
        context = {
            'enemy_count': len(enemies),
            'teammate_count': len(teammates),
            'health_ratio': self.health / self.max_health,
            'has_power_ups': len(self.power_ups) > 0,
            'objective_types': [obj.type for obj in objectives]
        }

        # Determine role-based behavior
        if self.role == RobotRole.SCAT:
            # Scout: prioritize finding enemies and mapping
            if enemies:
                return "engage_enemy"
            elif objectives:
                return "explore_objective"
            else:
                return "patrol"

        elif self.role == RobotRole.ATTACKER:
            # Attacker: focus on eliminating enemies
            if enemies:
                return "engage_enemy"
            elif objectives and objectives[0].type == ObjectiveType.CAPTURE_FLAG:
                return "capture_objective"
            else:
                return "patrol"

        elif self.role == RobotRole.DEFENDER:
            # Defender: protect objectives and base
            if objectives:
                for obj in objectives:
                    if obj.type in [ObjectiveType.DEFEND_BASE, ObjectiveType.CONTROL_POINT]:
                        # Find closest enemy to objective
                        enemies_near_objective = [
                            e for e in enemies 
                            if e.position.distance_to(obj.position) < obj.radius * 1.5
                        ]
                        if enemies_near_objective:
                            return "defend_objective"
                        else:
                            return "patrol_objective"
            return "patrol_base"

        elif self.role == RobotRole.SUPPORT:
            # Support: heal and buff teammates
            low_health_teammates = [t for t in teammates if t.health < t.max_health * 0.5]
            if low_health_teammates and self.secondary_weapon and self.secondary_weapon.weapon_type == WeaponType.SUPPORT:
                return "heal_teammate"
            elif enemies:
                return "provide_cover"
            else:
                return "patrol"

        elif self.role == RobotRole.CONTROLLER:
            # Controller: manipulate environment and coordinate
            if objectives:
                # If enemy near objective, try to disable
                for obj in objectives:
                    if obj.type == ObjectiveType.ESCAPE_PAYLOAD:
                        enemies_near = [e for e in enemies if e.position.distance_to(obj.position) < 100]
                        if enemies_near:
                            return "disrupt_enemy"

            # Look for power-ups to control
            power_ups_nearby = [p for p in arena.power_ups 
                              if p.position.distance_to(self.position) < 50]
            if power_ups_nearby:
                return "grab_power_up"

            return "coordinate_team"

        # Default fallback
        return "default"

    def is_alive(self) -> bool:
        return self.is_active and self.health > 0


@dataclass
class Objective:
    """Represents a game objective robots must complete."""
    id: str
    type: ObjectiveType
    position: Vector2D
    radius: float = 50.0
    team_required: RobotTeam = RobotTeam.NEUTRAL
    progress: float = 0.0  # 0.0 to 1.0
    captured_by: Optional[RobotTeam] = None
    is_active: bool = True
    required_teammates: int = 1  # number of teammates needed to complete
    completion_bonus: float = 100.0  # points awarded on completion
    capture_time: float = 10.0  # time to capture in seconds
    timer: float = 0.0

    def __post_init__(self):
        if not self.id:
            self.id = str(uuid.uuid4())

    def update(self, delta_time: float, robots: List[Robot]) -> bool:
        """Update objective progress based on nearby robots."""
        if not self.is_active:
            return False

        # Count robots of required team in radius
        nearby_robots = [
            r for r in robots 
            if r.team == self.team_required and r.is_active 
            and r.position.distance_to(self.position) <= self.radius
        ]

        if len(nearby_robots) >= self.required_teammates:
            self.timer += delta_time
            self.progress = min(1.0, self.timer / self.capture_time)

            if self.progress >= 1.0 and not self.captured_by:
                self.captured_by = self.team_required
                self.is_active = False  # Objective completed
                return True
        else:
            # Reduce progress if no robots nearby
            self.timer = max(0, self.timer - delta_time * 0.5)
            self.progress = self.timer / self.capture_time

        return False

    def reset(self):
        """Reset objective for reuse."""
        self.progress = 0.0
        self.captured_by = None
        self.is_active = True
        self.timer = 0.0


@dataclass
class PowerUp:
    """Represents a power-up item in the arena."""
    id: str
    type: PowerUpType
    position: Vector2D
    duration: float = 15.0  # seconds
    spawn_time: float = 0.0
    is_active: bool = True
    value: float = 25.0  # points value

    def __post_init__(self):
        if not self.id:
            self.id = str(uuid.uuid4())

    def apply(self, robot: Robot):
        """Apply this power-up to a robot."""
        robot.add_power_up(self.type, self.duration)
        self.is_active = False
        return self.value  # return points earned


@dataclass
class EnvironmentalHazardInstance:
    """Represents an active environmental hazard."""
    id: str
    hazard_type: EnvironmentalHazard
    position: Vector2D
    radius: float = 40.0
    damage_per_second: float = 5.0
    duration: float = 30.0
    timer: float = 0.0
    is_active: bool = True

    def __post_init__(self):
        if not self.id:
            self.id = str(uuid.uuid4())

    def update(self, delta_time: float, robots: List[Robot]):
        """Update hazard and apply damage to nearby robots."""
        self.timer += delta_time
        if self.timer >= self.duration:
            self.is_active = False
            return

        # Damage robots in range
        for robot in robots:
            if robot.is_active and robot.position.distance_to(self.position) <= self.radius:
                robot.take_damage(self.damage_per_second * delta_time, self.hazard_type.value)


@dataclass
class GameStats:
    """Tracks game statistics for scoring and adaptive difficulty."""
    score: Dict[RobotTeam, float] = field(default_factory=lambda: {
        RobotTeam.RED: 0.0,
        RobotTeam.BLUE: 0.0
    })
    objectives_completed: Dict[RobotTeam, int] = field(default_factory=lambda: {
        RobotTeam.RED: 0,
        RobotTeam.BLUE: 0
    })
    kills: Dict[RobotTeam, int] = field(default_factory=lambda: {
        RobotTeam.RED: 0,
        RobotTeam.BLUE: 0
    })
    deaths: Dict[RobotTeam, int] = field(default_factory=lambda: {
        RobotTeam.RED: 0,
        RobotTeam.BLUE: 0
    })
    team_work_bonus: Dict[RobotTeam, float] = field(default_factory=lambda: {
        RobotTeam.RED: 0.0,
        RobotTeam.BLUE: 0.0
    })
    last_update_time: float = 0.0
    battle_duration: float = 0.0

    def update(self, delta_time: float):
        self.battle_duration += delta_time
        self.last_update_time = time.time()

    def add_score(self, team: RobotTeam, points: float):
        self.score[team] += points
        if points > 0:
            self.team_work_bonus[team] += points * 0.1  # Bonus for teamwork

    def add_kill(self, team: RobotTeam):
        self.kills[team] += 1

    def add_death(self, team: RobotTeam):
        self.deaths[team] += 1

    def add_objective(self, team: RobotTeam):
        self.objectives_completed[team] += 1

    def get_team_performance(self, team: RobotTeam) -> float:
        """Calculate a performance score for adaptive difficulty."""
        score = self.score[team]
        kill_death_ratio = self.kills[team] / (self.deaths[team] + 1)
        objective_ratio = self.objectives_completed[team] / (self.battle_duration / 60 + 1)  # per minute
        teamwork_bonus = self.team_work_bonus[team]

        return score * 0.4 + kill_death_ratio * 10 + objective_ratio * 15 + teamwork_bonus * 0.2


class AdaptiveDifficulty:
    """Adaptive difficulty system that adjusts AI behavior based on performance."""

    def __init__(self, base_difficulty=0.5):
        self.base_difficulty = base_difficulty
        self.current_difficulty = base_difficulty
        self.difficulty_history = deque(maxlen=20)
        self.sensitivity = 0.1  # How quickly difficulty changes
        self.last_eval_time = time.time()
        self.evaluation_interval = 10.0  # seconds between evaluations

    def evaluate_and_adjust(self, stats: GameStats) -> float:
        """Evaluate team performance and adjust difficulty."""
        current_time = time.time()
        if current_time - self.last_eval_time < self.evaluation_interval:
            return self.current_difficulty

        # Get performance scores for both teams
        red_performance = stats.get_team_performance(RobotTeam.RED)
        blue_performance = stats.get_team_performance(RobotTeam.BLUE)

        # Find average performance
        avg_performance = (red_performance + blue_performance) / 2

        # Adjust difficulty based on average performance
        # If teams are doing too well, increase difficulty
        # If teams are struggling, decrease difficulty
        if avg_performance > 150:
            self.current_difficulty = min(1.0, self.current_difficulty + self.sensitivity)
        elif avg_performance < 50:
            self.current_difficulty = max(0.1, self.current_difficulty - self.sensitivity)

        # Store for tracking
        self.difficulty_history.append(self.current_difficulty)
        self.last_eval_time = current_time

        return self.current_difficulty

    def get_ai_aggressiveness(self) -> float:
        """Return AI aggressiveness level based on difficulty."""
        return self.current_difficulty * 0.8 + 0.2  # 0.2 to 1.0

    def get_ai_reaction_speed(self) -> float:
        """Return AI reaction speed multiplier."""
        return 1.0 + self.current_difficulty * 0.5  # 1.0 to 1.5

    def get_ai_vision_range(self) -> float:
        """Return AI vision range multiplier."""
        return 1.0 + self.current_difficulty * 0.3  # 1.0 to 1.3


@dataclass
class BattleResult:
    """Encapsulates the result of a battle."""
