    deaths: Dict[RobotTeam, int] = field(default_factory=dict)
    duration: float = 0.0
    winning_strategy: str = ""


class CyberArena:
    """Main game simulation for CyberArena multi-agent system."""

    def __init__(self, arena_size: Tuple[float, float] = (1000, 800)):
        self.arena_size = arena_size
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[EnvironmentalHazardInstance] = []
        self.projectiles: List[Dict] = []  # All active projectiles
        self.stats = GameStats()
        self.adaptive_difficulty = AdaptiveDifficulty()
        self.is_running = False
        self.game_time = 0.0

        # Audio/visual effects (simulated)
        self.particle_effects: List[Dict] = []
        self.sound_effects: List[str] = []

        # Control scheme (for future integration)
        self.control_scheme = "standard"

        # Initialize game
        self.reset()

    def reset(self):
        """Reset the entire arena to initial state."""
        self.robots = []
        self.objectives = []
        self.power_ups = []
        self.hazards = []
        self.projectiles = []
        self.particle_effects = []
        self.sound_effects = []
        self.stats = GameStats()
        self.game_time = 0.0
        self.adaptive_difficulty = AdaptiveDifficulty()

        # Create teams
        self.create_robots()
        self.create_objectives()
        self.create_power_ups()
        self.create_hazards()

    def create_robots(self):
        """Create initial robots with balanced teams and roles."""
        team_counts = {RobotTeam.RED: 4, RobotTeam.BLUE: 4}

        # Define role distribution
        role_distributions = {
            RobotTeam.RED: [
                RobotRole.ATTACKER,
                RobotRole.DEFENDER,
                RobotRole.SUPPORT,
                RobotRole.SCAT
            ],
            RobotTeam.BLUE: [
                RobotRole.ATTACKER,
                RobotRole.DEFENDER,
                RobotRole.SUPPORT,
                RobotRole.CONTROLLER
            ]
        }

        # Generate robots with positions
        for team, count in team_counts.items():
            for i in range(count):
                # Distribute positions around team base
                angle = i * (2 * math.pi / count)
                base_offset = 150 if team == RobotTeam.RED else self.arena_size[0] - 150
                x = base_offset + math.cos(angle) * 80
                y = self.arena_size[1] / 2 + math.sin(angle) * 80

                role = role_distributions[team][i % len(role_distributions[team])]

                # Create weapon based on role
                if role == RobotRole.ATTACKER:
                    weapon = Weapon(
                        name="Plasma Cannon",
                        weapon_type=WeaponType.RANGED,
                        damage=35,
                        range=350,
                        fire_rate=0.8,
                        ammo=60,
                        max_ammo=60,
                        spread=0.05,
                        projectile_speed=18.0
                    )
                elif role == RobotRole.DEFENDER:
                    weapon = Weapon(
                        name="Heavy Shield",
                        weapon_type=WeaponType.MELEE,
                        damage=50,
                        range=40,
                        fire_rate=1.5,
                        ammo=20,
                        max_ammo=20,
                        knockback=20.0
                    )
                elif role == RobotRole.SUPPORT:
                    weapon = Weapon(
                        name="Tactical Laser",
                        weapon_type=WeaponType.RANGED,
                        damage=20,
                        range=250,
                        fire_rate=0.4,
                        ammo=100,
                        max_ammo=100,
                        spread=0.08,
                        projectile_speed=12.0
                    )
                    secondary = Weapon(
                        name="Medi-Pulse",
                        weapon_type=WeaponType.SUPPORT,
                        damage=0,
                        range=80,
                        fire_rate=2.0,
                        ammo=10,
                        max_ammo=10
                    )
                else:  # SCAT or CONTROLLER
                    weapon = Weapon(
                        name="Smart Sniper",
                        weapon_type=WeaponType.RANGED,
                        damage=50,
                        range=500,
                        fire_rate=1.2,
                        ammo=40,
                        max_ammo=40,
                        spread=0.01,
                        projectile_speed=25.0
                    )
                    secondary = None

                robot = Robot(
                    robot_id=f"{team.value.lower()}_robot_{i}",
                    team=team,
                    role=role,
                    position=Vector2D(x, y),
                    health=100,
                    max_health=100,
                    armor=10,
                    speed=3.0,
                    weapon=weapon,
                    secondary_weapon=secondary if role == RobotRole.SUPPORT else None,
                    vision_range=250
                )
                self.robots.append(robot)

    def create_objectives(self):
        """Create game objectives."""
        # Capture Flag
        self.objectives.append(Objective(
            id="flag1",
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(self.arena_size[0] / 2, 150),
            team_required=RobotTeam.RED,
            radius=60,
            required_teammates=2,
            capture_time=15.0,
            completion_bonus=150
        ))

        self.objectives.append(Objective(
            id="flag2",
            type=ObjectiveType.CAPTURE_FLAG,
            position=Vector2D(self.arena_size[0] / 2, self.arena_size[1] - 150),
            team_required=RobotTeam.BLUE,
            radius=60,
            required_teammates=2,
            capture_time=15.0,
            completion_bonus=150
        ))

        # Control Point
        self.objectives.append(Objective(
            id="control1",
            type=ObjectiveType.CONTROL_POINT,
            position=Vector2D(self.arena_size[0] / 2, self.arena_size[1] / 2),
            team_required=RobotTeam.NEUTRAL,
            radius=80,
            required_teammates=1,
            capture_time=20.0,
            completion_bonus=100
        ))

        # Escort Payload (off-map)
        self.objectives.append(Objective(
            id="payload1",
            type=ObjectiveType.ESCAPE_PAYLOAD,
            position=Vector2D(100, self.arena_size[1] / 2),
            team_required=RobotTeam.RED,
            radius=30,
            required_teammates=3,
            capture_time=30.0,
            completion_bonus=200
        ))

    def create_power_ups(self):
        """Create initial power-up items."""
        powerup_positions = [
            Vector2D(200, 200),
            Vector2D(800, 200),
            Vector2D(200, 600),
            Vector2D(800, 600),
            Vector2D(self.arena_size[0] / 2, 400)
        ]

        powerup_types = [
            PowerUpType.HEALTH_PACK,
            PowerUpType.SPEED_BOOST,
            PowerUpType.SHIELD,
            PowerUpType.WEAPON_UPGRADE,
            PowerUpType.SAMPLER
        ]

        for i, pos in enumerate(powerup_positions):
            power_type = powerup_types[i % len(powerup_types)]
            power_up = PowerUp(
                id=f"powerup_{i}",
                type=power_type,
                position=pos,
                duration=15.0
            )
            self.power_ups.append(power_up)

    def create_hazards(self):
        """Create environmental hazards."""
        hazard_positions = [
            Vector2D(300, 400),
            Vector2D(700, 400),
            Vector2D(500, 200),
            Vector2D(500, 600)
        ]

        hazard_types = [
            EnvironmentalHazard.ELECTRIC_FIELD,
            EnvironmentalHazard.FLAME_ZONE,
            EnvironmentalHazard.GRAVITY_WELL,
            EnvironmentalHazard.MINEFIELD
        ]

        for i, pos in enumerate(hazard_positions):
            hazard_type = hazard_types[i % len(hazard_types)]
            hazard = EnvironmentalHazardInstance(
                id=f"hazard_{i}",
                hazard_type=hazard_type,
                position=pos,
                radius=50,
                damage_per_second=4.0,
                duration=45.0
            )
            self.hazards.append(hazard)

    def update(self, delta_time: float):
        """Update the entire simulation state."""
        if not self.is_running:
            return

        self.game_time += delta_time
        self.stats.update(delta_time)

        # Update adaptive difficulty
        self.adaptive_difficulty.evaluate_and_adjust(self.stats)

        # Update robots
        for robot in self.robots:
            if not robot.is_active:
                continue

            # Update power-ups
            robot.update_power_ups(delta_time)

            # Update weapons
            robot.update_weapon(delta_time)

            # AI decision making
            ai_decision = robot.calculate_ai_decision(self)

            # Execute decision
            self.execute_ai_decision(robot, ai_decision, delta_time)

            # Apply physics
            robot.position.x = max(0, min(robot.position.x, self.arena_size[0]))
            robot.position.y = max(0, min(robot.position.y, self.arena_size[1]))

            # Apply damage from hazards
            for hazard in self.hazards:
                if hazard.is_active and robot.position.distance_to(hazard.position) <= hazard.radius:
                    robot.take_damage(hazard.damage_per_second * delta_time, hazard.hazard_type.value)

        # Update objectives
        for objective in self.objectives:
            if objective.update(delta_time, self.robots):
                # Objective completed
                if objective.captured_by:
                    self.stats.add_objective(objective.captured_by)
                    self.stats.add_score(objective.captured_by, objective.completion_bonus)

                    # Create feedback effect
                    self.add_particle_effect(objective.position, "objective_complete", 5)
                    self.add_sound_effect("objective_completed")

                # Reset objective after delay
                if objective.captured_by:
                    # Reset after 10 seconds
                    pass

        # Update power-ups
        for power_up in self.power_ups:
            if not power_up.is_active:
                continue

            # Check for robot pickup
            for robot in self.robots:
                if robot.is_active and robot.position.distance_to(power_up.position) < 30:
                    points = power_up.apply(robot)
                    self.stats.add_score(robot.team, points)
                    self.add_particle_effect(power_up.position, "powerup_collected", 8)
                    self.add_sound_effect("powerup_collected")
                    break

        # Update hazards
        for hazard in self.hazards:
            hazard.update(delta_time, self.robots)

        # Update projectiles
        self.update_projectiles(delta_time)

        # Update particle effects
        self.update_particle_effects(delta_time)

        # Check for game end condition
        self.check_game_end()

    def execute_ai_decision(self, robot: Robot, decision: str, delta_time: float):
        """Execute AI decision for a robot."""
        enemies = robot.get_sensed_enemies(self.robots)
        teammates = [r for r in self.robots if r.team == robot.team and r.is_active]
        objectives = [obj for obj in self.objectives if obj.is_active]

        # Get difficulty modifiers
        aggressiveness = self.adaptive_difficulty.get_ai_aggressiveness()
        reaction_speed = self.adaptive_difficulty.get_ai_reaction_speed()
        vision_multiplier = self.adaptive_difficulty.get_ai_vision_range()

        # Adjust robot parameters for difficulty
        robot.vision_range = 250 * vision_multiplier

        if decision == "engage_enemy" and enemies:
            # Find closest enemy
            closest_enemy = min(enemies, key=lambda e: robot.position.distance_to(e.position))
            target_pos = closest_enemy.position

            # Move toward enemy
            robot.move_towards(target_pos, delta_time * reaction_speed)

            # Fire at enemy
            if robot.weapon.can_fire() and robot.position.distance_to(target_pos) < robot.weapon.range:
                projectile = robot.fire_at(target_pos)
                if projectile:
                    self.projectiles.append(projectile)

                    # Add feedback
                    self.add_particle_effect(projectile['position'], "bullet_impact", 3)
                    self.add_sound_effect("weapon_fire")

                    # Record success
                    robot.add_strategy_memory("engage_enemy", {"enemy_count": len(enemies)}, "success")

        elif decision == "capture_objective" and objectives:
            # Find closest objective to capture
            closest_obj = min(objectives, key=lambda o: robot.position.distance_to(o.position))
            if closest_obj.team_required == robot.team or closest_obj.team_required == RobotTeam.NEUTRAL:
                robot.move_towards(closest_obj.position, delta_time)

