@dataclass
class Vector2D:
    """2D position and velocity vector."""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def rotate(self, angle_radians):
        cos_a = math.cos(angle_radians)
        sin_a = math.sin(angle_radians)
        return Vector2D(
            self.x * cos_a - self.y * sin_a,
            self.x * sin_a + self.y * cos_a
        )

    def to_tuple(self):
        return (self.x, self.y)


@dataclass
class Weapon:
    """Represents a weapon with attributes and behavior."""
    name: str
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    cooldown: float = 0.0  # current cooldown
    ammo: int = 100
    max_ammo: int = 100
    spread: float = 0.0  # angular spread for ranged weapons
    knockback: float = 0.0
    projectile_speed: float = 10.0  # for ranged weapons
    area_effect_radius: float = 0.0  # for explosives

    def can_fire(self):
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self):
        if self.can_fire():
            self.ammo -= 1
            self.cooldown = self.fire_rate
            return True
        return False

    def update(self, delta_time: float):
        if self.cooldown > 0:
            self.cooldown -= delta_time
        if self.ammo < self.max_ammo:
            # Recharge ammo over time (slowly)
            self.ammo = min(self.max_ammo, self.ammo + delta_time * 0.5)


