        RobotTeam.RED: 0.0,
        RobotTeam.BLUE: 0.0
    })
    last_update_time: float = 0.0
    battle_duration: float = 0.0

    def update(self, delta_time: float):
        self.battle_duration += delta_time
        self.last_update_time = time.time()

    def add_score(self, team: RobotTeam, points: float):
        self.score[team] += points
        if points > 0:
            self.team_work_bonus[team] += points * 0.1  # Bonus for teamwork

    def add_kill(self, team: RobotTeam):
        self.kills[team] += 1

    def add_death(self, team: RobotTeam):
        self.deaths[team] += 1

    def add_objective(self, team: RobotTeam):
        self.objectives_completed[team] += 1

    def get_team_performance(self, team: RobotTeam) -> float:
        """Calculate a performance score for adaptive difficulty."""
        score = self.score[team]
        kill_death_ratio = self.kills[team] / (self.deaths[team] + 1)
        objective_ratio = self.objectives_completed[team] / (self.battle_duration / 60 + 1)  # per minute
        teamwork_bonus = self.team_work_bonus[team]

        return score * 0.4 + kill_death_ratio * 10 + objective_ratio * 15 + teamwork_bonus * 0.2


class AdaptiveDifficulty:
    """Adaptive difficulty system that adjusts AI behavior based on performance."""

    def __init__(self, base_difficulty=0.5):
        self.base_difficulty = base_difficulty
        self.current_difficulty = base_difficulty
        self.difficulty_history = deque(maxlen=20)
        self.sensitivity = 0.1  # How quickly difficulty changes
        self.last_eval_time = time.time()
        self.evaluation_interval = 10.0  # seconds between evaluations

    def evaluate_and_adjust(self, stats: GameStats) -> float:
        """Evaluate team performance and adjust difficulty."""
        current_time = time.time()
        if current_time - self.last_eval_time < self.evaluation_interval:
            return self.current_difficulty

        # Get performance scores for both teams
        red_performance = stats.get_team_performance(RobotTeam.RED)
        blue_performance = stats.get_team_performance(RobotTeam.BLUE)

        # Find average performance
        avg_performance = (red_performance + blue_performance) / 2

        # Adjust difficulty based on average performance
        # If teams are doing too well, increase difficulty
        # If teams are struggling, decrease difficulty
        if avg_performance > 150:
            self.current_difficulty = min(1.0, self.current_difficulty + self.sensitivity)
        elif avg_performance < 50:
            self.current_difficulty = max(0.1, self.current_difficulty - self.sensitivity)

        # Store for tracking
        self.difficulty_history.append(self.current_difficulty)
        self.last_eval_time = current_time

        return self.current_difficulty

    def get_ai_aggressiveness(self) -> float:
        """Return AI aggressiveness level based on difficulty."""
        return self.current_difficulty * 0.8 + 0.2  # 0.2 to 1.0

    def get_ai_reaction_speed(self) -> float:
        """Return AI reaction speed multiplier."""
        return 1.0 + self.current_difficulty * 0.5  # 1.0 to 1.5

    def get_ai_vision_range(self) -> float:
        """Return AI vision range multiplier."""
        return 1.0 + self.current_difficulty * 0.3  # 1.0 to 1.3


